      B.innerHTML = `${ganttHtml(p)}<button class="btn" id="phAdd" style="align-self:flex-start">${ico('plus', 'sm')}Aggiungi fase</button>`;
      wireGantt(B, p, paint, persist);
      $('#phAdd', B).onclick = () => editPhase(p, null, paint, persist);
