    this.showing = true;
    const el = document.createElement('div'); el.className = 'ach-toast'; el.style.setProperty('--tc', T[1]);
    el.innerHTML = `<span class="ach-medal">${ico(a.i)}</span><span style="min-width:0"><small>${a.hidden ? 'Trofeo segreto sbloccato' : 'Trofeo sbloccato'} · ${T[0]}</small><b>${esc(a.n)}</b></span><span class="ach-xp">+${T[3]} XP</span>`;
