{ const old = Game.checkBadges.bind(Game); Game.checkBadges = function () { old(); Trophies.check(); }; }

/* ---------- Streak shield ---------- */
Game.streak = function () {
  const s = S.game.streak, t = todayK();
  if (s.last === t) return;
  if (s.last === addDK(t, -1)) s.count++;
  else if (s.last === addDK(t, -2) && (S.game.shields || 0) > 0) { S.game.shields--; s.count++; setTimeout(() => Island.toast({ icon: 'lock', c: 'var(--blue)', t: 'Scudo usato', s: `Serie salvata: ${s.count} giorni`, ms: 3200 }), 600); }
  else s.count = 1;
  s.last = t; s.best = Math.max(s.best || 0, s.count);
  if (s.count % 7 === 0 && (S.game.shields || 0) < 3) { S.game.shields = (S.game.shields || 0) + 1; setTimeout(() => Island.toast({ icon: 'lock', c: 'var(--blue)', t: 'Scudo guadagnato', s: '7 giorni di fila: un giorno saltato non spezzerà la serie', ms: 3600 }), 900); }
};
Game.currentStreak = function () { const s = S.game.streak, t = todayK(); return (s.last === t || s.last === addDK(t, -1) || (s.last === addDK(t, -2) && (S.game.shields || 0) > 0)) ? s.count : 0; };
{ // level-up rewards
  const oldAdd = Game.add.bind(Game);
  Game.add = function (amount, reason, opts) {
    const before = this.levelOf(S.game.xp); oldAdd(amount, reason, opts); const after = this.levelOf(S.game.xp);
    if (after > before) for (const r of REWARDS) if (r.lv > before && r.lv <= after) {
      if (r.type === 'shield') S.game.shields = Math.min(3, (S.game.shields || 0) + 1);
      setTimeout(() => Island.toast({ icon: 'star', c: 'var(--purple)', t: 'Ricompensa sbloccata', s: r.n, ms: 3400 }), 3800);
    }
  };
}
{ const o = Game.add.bind(Game); Game.add = function (...a) { o(...a); clearTimeout(Boss._t); Boss._t = setTimeout(() => Boss.hits(), 800); }; }
/* sound packs */
{ const tone = Sound.tone.bind(Sound);
  Sound.tone = function (freqs, dur, gap, vol) {
    const p = S.profile.sound || 'base';
    if (p === 'crystal' && unlocked(3)) return tone(freqs.map(f => f * 2), dur * 1.4, gap, vol * .8);
    if (p === 'arcade' && unlocked(12)) { const c = this.ensure(); if (!c) return; freqs.forEach((f, i) => { const o = c.createOscillator(), g = c.createGain(), t = c.currentTime + i * (gap || .07) * .8; o.type = 'square'; o.frequency.value = f / 2; g.gain.setValueAtTime(0, t); g.gain.linearRampToValueAtTime((vol || .1) * .35, t + .005); g.gain.exponentialRampToValueAtTime(.0001, t + (dur || .2) * .7); o.connect(g).connect(c.destination); o.start(t); o.stop(t + dur); }); return; }
    return tone(freqs, dur, gap, vol);
  };
}

/* ---------- Weekly challenges ---------- */
const WEEKLY = [
  { id: 'wfocus', t: '5 ore di focus', k: 'focus', n: 300, xp: 150, i: 'timer' },
  { id: 'wfocus2', t: '8 ore di focus', k: 'focus', n: 480, xp: 220, i: 'flame' },
  { id: 'wtasks', t: 'Completa 20 promemoria', k: 'tasks', n: 20, xp: 120, i: 'check' },
  { id: 'wcards', t: 'Ripassa 100 flashcard', k: 'cards', n: 100, xp: 140, i: 'cards' },
  { id: 'whabits', t: 'Spunta le abitudini 15 volte', k: 'habits', n: 15, xp: 120, i: 'heart' },
  { id: 'wjournal', t: 'Scrivi 5 pagine di diario', k: 'journal', n: 5, xp: 100, i: 'pencil' },
  { id: 'wtopics', t: 'Fai avanzare 10 argomenti', k: 'topics', n: 10, xp: 140, i: 'book' },
  { id: 'wsims', t: '2 simulazioni d\'esame', k: 'sims', n: 2, xp: 150, i: 'grad' },
  { id: 'wnotes', t: 'Lavora su 6 note', k: 'notes', n: 6, xp: 100, i: 'note' },
];
const Weekly = {
  wk() { return dkey(startOfWeek(new Date())); },
  list() {
    const w = this.wk(); let h = 7; for (const ch of w) h = (h * 33 + ch.charCodeAt(0)) >>> 0;
    const picks = [], pool = WEEKLY.slice();
    while (picks.length < 3 && pool.length) { const i = h % pool.length; picks.push(pool.splice(i, 1)[0]); h = (h * 1103515245 + 12345) >>> 0; }
    const end = addDK(w, 6);
    return picks.map(c => { const prog = Math.min(c.n, sumDays(c.k, w, end)); return { ...c, prog, done: prog >= c.n, claimed: !!(S.game.wclaim || {})[w + ':' + c.id] }; });
  },
  claim(id) {
    const w = this.wk(), c = this.list().find(x => x.id === id); if (!c || !c.done || c.claimed) return;
    (S.game.wclaim ||= {})[w + ':' + id] = 1; S.game.weeklyDone = (S.game.weeklyDone || 0) + 1;
    const ks = Object.keys(S.game.wclaim); if (ks.length > 30) ks.slice(0, ks.length - 30).forEach(k => delete S.game.wclaim[k]);
    Game.add(c.xp, 'Sfida settimanale: ' + c.t, { icon: 'trophy' }); confetti(120);
  },
};
ACT.wclaim = el => { Weekly.claim(el.dataset.id); App.refresh(); };

/* ---------- Bosses: upcoming exams ---------- */
const Boss = {
  courseFor(x) { return S.courses.find(c => c.examId === x.id) || S.courses.find(c => c.name.toLowerCase() === x.name.toLowerCase()); },
  list() { const t = todayK(); return S.exams.filter(x => x.status === 'planned' && x.date && x.date >= t).sort((a, b) => a.date.localeCompare(b.date)).map(x => this.state(x)); },
  state(x) {
    const c = this.courseFor(x);
    const topics = c ? Courses.prog(c) : 0;
    const cards = c ? (() => { const cs = Courses.notes(c).flatMap(n => n.cards || []); return cs.length ? cs.filter(k => (k.reps || 0) >= 2).length / cs.length : null; })() : null;
    const sims = c && (c.sims || []).length ? Math.max(...c.sims.slice(-3).map(s => s.v)) : null;
    const focusH = c ? minsTot(c.min) / 60 : 0, focusGoal = Math.max(6, (+x.cfu || 6) * 2);
    let dmg = topics * 45 + Math.min(1, focusH / focusGoal) * 25;
    dmg += cards == null ? (topics * 15) : cards * 15;
    dmg += sims == null ? 0 : clamp((sims - 15) / 15, 0, 1) * 15;
    const hp = Math.round(clamp(100 - dmg, 0, 100));
    return { x, c, hp, days: dayDiff(todayK(), x.date), parts: { topics, cards, sims, focusH, focusGoal } };
  },
  hits() {
    S.game.bossHP ||= {};
    for (const b of this.list()) {
      const prev = S.game.bossHP[b.x.id];
      if (prev != null && b.hp < prev) { const d = prev - b.hp; Island.toast({ icon: 'bolt', c: 'var(--red)', t: d >= 8 ? 'Colpo critico!' : 'Colpo a segno', s: `${b.x.name}: −${d} HP`, end: `${b.hp} HP`, ms: 2600 }); }
      if (prev !== b.hp) { S.game.bossHP[b.x.id] = b.hp; save('game'); }
    }
  },
  defeated(x) {
    if (S.game.bossHP && S.game.bossHP[x.id] != null) {
      delete S.game.bossHP[x.id]; S.game.bossKills = (S.game.bossKills || 0) + 1;
      setTimeout(() => { Island.toast({ icon: 'trophy', c: 'var(--yellow)', t: 'Boss sconfitto!', s: x.name, end: '+150 XP', ms: 4200 }); Game.add(150, 'Boss sconfitto: ' + x.name, { silent: true }); confetti(260); }, 1200);
    }
  },
  card(b, big) {
    const col = b.hp > 60 ? 'var(--red)' : b.hp > 25 ? 'var(--orange)' : 'var(--green)', P = b.parts;
    return `<button class="boss ${big ? 'big' : ''}" data-boss="${b.x.id}"><div class="boss-top"><span class="boss-ico">${ico('bolt')}</span><div style="min-width:0;flex:1"><small>Boss · ${b.days === 0 ? 'oggi la battaglia' : b.days === 1 ? 'battaglia domani' : `battaglia tra ${b.days} giorni`}</small><b>${esc(b.x.name)}</b></div><span class="boss-lv">Lv ${b.x.cfu || '?'}</span></div>
      <div class="boss-hp"><i style="width:${b.hp}%;background:${col}"></i><span>${b.hp} / 100 HP</span></div>
      ${big ? `<div class="boss-parts">${[[`Programma ${Math.round(P.topics * 100)}%`, P.topics], [`Focus ${P.focusH.toFixed(1).replace('.', ',')}/${P.focusGoal} h`, Math.min(1, P.focusH / P.focusGoal)], [P.cards == null ? 'Flashcard: nessuna' : `Flashcard solide ${Math.round(P.cards * 100)}%`, P.cards || 0], [P.sims == null ? 'Simulazioni: nessuna' : `Miglior simulazione ${P.sims}`, P.sims == null ? 0 : clamp((P.sims - 15) / 15, 0, 1)]].map(([l, v]) => `<span><i style="--p:${v * 100}%"></i>${l}</span>`).join('')}</div>${!b.c ? `<div class="muted" style="font-size:12px;margin-top:6px">Collega un corso a questo esame per infliggere danni studiando.</div>` : ''}` : ''}</button>`;
  },
};
document.addEventListener('click', e => { const b = e.target.closest('[data-boss]'); if (!b) return; const x = S.exams.find(z => z.id === b.dataset.boss); const c = x && Boss.courseFor(x); c ? openCourse(c.id) : editExam(b.dataset.boss); });
/* count topic advances and simulations for weekly challenges + boss hits */
