function aiSectionMount(root) {
    $$('[data-aip]', root).forEach(r => { const pick = () => { UI.aiSel = r.dataset.aip; UI.aiInfo = null; App.render(); if (AIX.P[UI.aiSel].noKey || AIX.keyed[UI.aiSel]) ACT.aiModels(); }; r.onclick = pick; r.onkeydown = e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); pick(); } }; });
    const k = $('#aiKey', root); if (k) k.onkeydown = e => { if (e.key === 'Enter') ACT.aiSaveKey(); };
    const sel = UI.aiSel || AIX.conf().provider || 'gemini';
    if ((AIX.P[sel].noKey || AIX.keyed[sel]) && !AIX.models[sel] && !UI.aiLoading) ACT.aiModels();
}
if (DESK || !IN_CLAUDE) {
  const curSel = () => UI.aiSel || AIX.conf().provider || 'gemini';
  ACT.aiKeyLink = () => AIX.T.open(AIX.P[curSel()].key);
  ACT.aiSaveKey = async () => {
    const p = curSel(), el = $('#aiKey'); const v = el && el.value.trim(); if (!v) return;
    await AIX.T.secret.set('ai.' + p, v); if (AIX.T === DESK && !AIX.P[p].noKey) await AIK.set(p, v); AIX.keyed[p] = true; delete AIX.models[p];
    Island.toast({ icon: 'check', c: 'var(--green)', t: 'Chiave salvata', s: 'Ora scegli il modello', ms: 2200 });
    await ACT.aiModels();
  };
  ACT.aiDelKey = async () => {
    const p = curSel(); await AIX.T.secret.set('ai.' + p, ''); if (AIX.T === DESK) await AIK.set(p, ''); AIX.keyed[p] = false; delete AIX.models[p];
    const c = AIX.conf(); if (c.provider === p) { AIX.setConf({}); AIX.ok = false; }
    App.render();
  };
  ACT.aiModels = async () => {
    const p = curSel(); UI.aiLoading = 1;
    try { await AIX.loadModels(p); } finally { UI.aiLoading = 0; }
    const M = AIX.models[p];
    if (M.list && M.list.length && (!AIX.ok || AIX.conf().provider !== p)) { /* first time: select the best model automatically */
      AIX.setConf({ provider: p, model: AIX.pickModel(p, M.list) }); AIX.ok = true;
      Island.toast({ icon: 'spark', c: 'var(--purple)', t: 'Segretario attivo', s: AIX.label(), ms: 2600 });
    } else if (M.list && !M.list.length) M.err = { code: 'empty', message: p === 'ollama' ? 'Nessun modello installato: scrivi “ollama pull qwen3:8b” nel Terminale.' : 'Nessun modello disponibile.' };
    if (UI.view === 'account') App.render();
  };
  ACT.aiUse = () => {
    const p = curSel(), m = $('#aiModel') && $('#aiModel').value; if (!m) return;
    AIX.setConf({ provider: p, model: m }); AIX.ok = true; UI.aiInfo = null;
    Island.toast({ icon: 'spark', c: 'var(--purple)', t: 'Segretario attivo', s: AIX.label(), ms: 2400 }); App.render();
  };
  ACT.aiTest = async el => {
    if (el) el.disabled = true; UI.aiInfo = { test: 'Provo…' }; App.render();
    try { const t0 = performance.now(); const { text } = await AIX.sample('Rispondi in italiano con una sola frase breve e simpatica: sei pronto ad aiutarmi a organizzare studio e lavoro?'); UI.aiInfo = { test: `“${text.slice(0, 160)}” · ${((performance.now() - t0) / 1000).toFixed(1)} s` }; }
    catch (e) { UI.aiInfo = { test: 'Non funziona: ' + ((e && e.message) || 'errore') }; }
    App.render();
  };
}

