/* =========================================================
   PERSONALIZZAZIONE — colore libero, carattere, densità,
   sfondo, angoli, pagina iniziale.
   ========================================================= */
const UIX = {
  FONTS: { system: ['Sistema', 'var(--f-sys)'], rounded: ['Arrotondato', 'ui-rounded,"SF Pro Rounded","Nunito","Segoe UI",system-ui,sans-serif'], serif: ['Classico', 'ui-serif,"New York","Iowan Old Style",Georgia,"Times New Roman",serif'], mono: ['Tecnico', 'ui-monospace,"SF Mono",Menlo,Consolas,monospace'] },
  AMB: { off: ['Spento', 0], soft: ['Leggero', .18], normal: ['Normale', null], vivid: ['Intenso', .62] },
  get p() { return S.profile.ui || {}; },
  set(k, v) { S.profile.ui = { ...(S.profile.ui || {}), [k]: v }; save('profile'); this.apply(); },
  apply() {
    const p = this.p, r = document.documentElement, st = r.style;
    if (!r.style.getPropertyValue('--f-sys')) st.setProperty('--f-sys', getComputedStyle(r).getPropertyValue('--f-ui') || 'system-ui');
    if (p.accentCustom && S.profile.accent === 'custom') { st.setProperty('--accent-l', p.accentCustom); st.setProperty('--accent-d', mixHex(p.accentCustom, '#ffffff', .18)); }
    const f = this.FONTS[p.font || 'system']; if (p.font && p.font !== 'system') st.setProperty('--f-ui', f[1]); else st.setProperty('--f-ui', st.getPropertyValue('--f-sys'));
    r.classList.toggle('compact', p.density === 'compact');
    r.classList.toggle('square', p.corners === 'square');
    const a = this.AMB[p.ambient || 'normal'][1]; if (a == null) st.removeProperty('--amb-a'); else st.setProperty('--amb-a', a);
    r.classList.toggle('no-amb', p.ambient === 'off');
    r.classList.toggle('reduce-glass', !!p.solid);
  },
  html() {
    const p = this.p, P = S.profile, views = [['last', 'Ultima aperta'], ['today', 'Oggi'], ['calendar', 'Calendario'], ['tasks', 'Promemoria'], ['notes', 'Note'], ['focus', 'Focus'], ['money', 'Finanze'], ['assistant', 'Segretario']];
    return `<div class="section-h">Personalizzazione</div>
      <div class="list flat">
        <div class="row"><span class="t" style="width:150px">Colore libero</span><span class="grow muted" style="font-size:14px">Scegli qualsiasi colore per l'app</span><label class="color-pick" style="--c:${esc(p.accentCustom || '#007AFF')}"><input type="color" id="uxAcc" value="${esc(p.accentCustom || '#007AFF')}" aria-label="Colore personalizzato"></label>${P.accent === 'custom' ? `<button class="btn sm" id="uxAccOff">Usa i preset</button>` : ''}</div>
        <div class="row"><span class="t" style="width:150px">Carattere</span>${seg('uxF', Object.entries(this.FONTS).map(([k, v]) => [k, v[0]]), p.font || 'system')}</div>
        <div class="row"><span class="t" style="width:150px">Densità</span>${seg('uxD', [['comfort', 'Comoda'], ['compact', 'Compatta']], p.density || 'comfort')}</div>
        <div class="row"><span class="t" style="width:150px">Angoli</span>${seg('uxC', [['round', 'Arrotondati'], ['square', 'Squadrati']], p.corners || 'round')}</div>
        <div class="row"><span class="t" style="width:150px">Luci di sfondo</span>${seg('uxA', Object.entries(this.AMB).map(([k, v]) => [k, v[0]]), p.ambient || 'normal')}</div>
        <div class="row"><span class="grow"><div class="t">Superfici solide</div><div class="s">Meno trasparenza: più contrasto e più leggera sui computer vecchi</div></span>${toggleBtn('uxS', !!p.solid)}</div>
        <div class="row"><span class="t" style="width:150px">All'avvio apri</span><select class="input" id="uxStart" style="max-width:220px">${views.map(([k, l]) => `<option value="${k}" ${(p.start || 'last') === k ? 'selected' : ''}>${l}</option>`).join('')}</select></div>
      </div>`;
  },
  wire(root) {
    const acc = $('#uxAcc', root); if (acc) acc.oninput = () => { acc.parentElement.style.setProperty('--c', acc.value); S.profile.accent = 'custom'; S.profile.ui = { ...(S.profile.ui || {}), accentCustom: acc.value }; this.apply(); }; if (acc) acc.onchange = () => { save('profile'); App.render(); };
    const off = $('#uxAccOff', root); if (off) off.onclick = () => { S.profile.accent = 'blue'; save('profile'); applyTheme(); App.render(); };
    wireSeg(root, 'uxF', v => this.set('font', v)); wireSeg(root, 'uxD', v => this.set('density', v)); wireSeg(root, 'uxC', v => this.set('corners', v)); wireSeg(root, 'uxA', v => this.set('ambient', v));
    const s = $('#uxS', root); if (s) wireToggle(s, on => this.set('solid', on));
    const st = $('#uxStart', root); if (st) st.onchange = () => this.set('start', st.value);
  },
};
function mixHex(a, b, t) { const p = h => [1, 3, 5].map(i => parseInt(h.slice(i, i + 2), 16)); const x = p(a), y = p(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * t).toString(16).padStart(2, '0')).join(''); }
