const ALERT_OPTS = [['', 'Predefinito'], ['none', 'Nessun avviso'], ['0', "All'ora esatta"], ['5', '5 minuti prima'], ['10', '10 minuti prima'], ['15', '15 minuti prima'], ['30', '30 minuti prima'], ['60', '1 ora prima'], ['120', '2 ore prima'], ['1440', '1 giorno prima']];
