    let r; try { r = await fetch(this.fnUrl(), { headers: { apikey: Cloud.cfg.key, Authorization: 'Bearer ' + Cloud.cfg.key } }); } catch (_) { throw new Error('La funzione non risponde: controlla di averla creata con il nome orbita-push'); }
    const j = await r.json().catch(() => ({}));
