    if (this.ios() && !this.standalone()) { Island.toast({ icon: 'bolt', c: 'var(--orange)', t: 'Prima aggiungi Orbita alla schermata Home', s: 'Condividi › Aggiungi alla schermata Home, poi aprilo da lì', ms: 4800 }); return false; }
