{ const g = NAV.find(x => x.g === 'Vita') || NAV[0]; g.items.unshift(['messages', 'Messaggi', 'chat']); }
TITLES.messages = 'Messaggi';
const WA = window.orbitaDesktop && window.orbitaDesktop.wa ? window.orbitaDesktop.wa : null;
const APPS = { whatsapp: ['WhatsApp', '#25D366', 'chat'], sms: ['SMS', '#34C759', 'chat'], imessage: ['iMessage', '#0A84FF', 'chat'], mail: ['Email', '#007AFF', 'mail'], altro: ['Notifica', '#8E8E93', 'bolt'] };
