  const n = Notes.create({ title: T, html: `<p><i>${names[kind]} · ${when}${dur ? ' · ' + dur + ' min' : ''}${audioName ? ' · audio in Documenti' : ''}</i></p><h2>Trascrizione</h2>${paras}`, text: text || '' });
