    const sum = (out.summary || []).filter(Boolean), todo = (out.todo || []).filter(Boolean);
    n.html = `${n.html.split('<h2>Trascrizione</h2>')[0]}<div class="ai-sum"><b>Riassunto</b><ul>${sum.map(s => `<li>${esc(s)}</li>`).join('')}</ul></div>${todo.length ? `<h2>Cose da fare</h2><ul class="cl">${todo.map(s => `<li>${esc(s)}</li>`).join('')}</ul>` : ''}<h2>Trascrizione</h2>${n.html.split('<h2>Trascrizione</h2>')[1] || ''}`;
