/* ---------- split expenses ---------- */
const Split = {
  g(id) { return S.split.find(x => x.id === id); },
  shares(e, g) { const ids = e.who && e.who.length ? e.who : g.members.map(m => m.id); if (e.custom) return e.custom; const each = Math.round(e.amt / ids.length * 100) / 100, out = {}; ids.forEach((id, i) => out[id] = i === 0 ? Math.round((e.amt - each * (ids.length - 1)) * 100) / 100 : each); return out; },
  balances(g) { const b = Object.fromEntries(g.members.map(m => [m.id, 0])); for (const e of g.exp || []) { b[e.payer] = (b[e.payer] || 0) + e.amt; for (const [id, v] of Object.entries(this.shares(e, g))) b[id] = (b[id] || 0) - v; } for (const k in b) b[k] = Math.round(b[k] * 100) / 100; return b; },
  /** fewest transfers to settle up */
  settle(g) { const b = this.balances(g), cr = Object.entries(b).filter(([, v]) => v > 0.004).map(([k, v]) => [k, v]).sort((a, b) => b[1] - a[1]), db = Object.entries(b).filter(([, v]) => v < -0.004).map(([k, v]) => [k, -v]).sort((a, b) => b[1] - a[1]), out = []; let i = 0, j = 0; while (i < cr.length && j < db.length) { const x = Math.min(cr[i][1], db[j][1]); out.push({ from: db[j][0], to: cr[i][0], amt: Math.round(x * 100) / 100 }); cr[i][1] -= x; db[j][1] -= x; if (cr[i][1] < 0.005) i++; if (db[j][1] < 0.005) j++; } return out; },
  name(g, id) { const m = g.members.find(x => x.id === id); return m ? m.name : '?'; },
  me(g) { return this.balances(g).me || 0; },
};
VIEWS.split = {
  actions: () => (UI.splitTab || 'groups') === 'groups' ? `<button class="btn primary sm" data-act="newGroup">${ico('plus', 'sm')}Gruppo</button>` : `<button class="btn primary sm" data-act="newLoan">${ico('plus', 'sm')}Prestito</button>`,
  render() {
    const tab = UI.splitTab || 'groups', tot = S.split.reduce((s, g) => s + Split.me(g), 0);
    const tabs = seg('spt', [['groups', 'Spese divise'], ['loans', `Prestiti${S.loans.filter(l => !l.done).length ? ' · ' + S.loans.filter(l => !l.done).length : ''}`]], tab);
    if (tab === 'loans') {
      const open = S.loans.filter(l => !l.done).sort((a, b) => (a.due || '9').localeCompare(b.due || '9')), done = S.loans.filter(l => l.done);
      const row = l => `<button class="row" data-loan="${l.id}"><span class="tile-ico" style="background:${l.dir === 'out' ? 'var(--orange)' : 'var(--blue)'}">${ico(l.kind === 'oggetto' ? 'folder' : 'wallet')}</span><span class="grow" style="min-width:0"><div class="t">${l.dir === 'out' ? 'A' : 'Da'} ${esc(l.who)}: ${l.kind === 'oggetto' ? esc(l.what) : eur(l.amt)}</div><div class="s">${relDay(l.date, true)}${l.due ? ` · da restituire ${relDay(l.due, true).toLowerCase()}` : ''}${l.kind !== 'oggetto' && l.what ? ' · ' + esc(l.what) : ''}</div></span>${l.done ? '' : `<span class="pill c" style="--c:${l.due && l.due < todayK() ? 'var(--red)' : 'var(--gray)'}">${l.dir === 'out' ? 'ti deve' : 'devi'}</span>`}</button>`;
      return `<h1 class="large-title">Conti con gli altri</h1><p class="subtitle">Soldi e oggetti che hai prestato o che ti hanno prestato.</p><div style="margin-bottom:14px">${tabs}</div>
        ${open.length ? `<div class="list">${open.map(row).join('')}</div>` : `<div class="card"><div class="empty">${ico('wallet')}<b>Nessun prestito aperto</b><p>Segna cosa presti (soldi, libri, attrezzi…) e a chi: ti ricordo di farteli restituire.</p></div></div>`}
        ${done.length ? `<div class="section-h">Restituiti</div><div class="list">${done.slice(-10).reverse().map(row).join('')}</div>` : ''}`;
    }
    return `<h1 class="large-title">Conti con gli altri</h1><p class="subtitle">${S.split.length ? (Math.abs(tot) < 0.01 ? 'Sei in pari con tutti.' : tot > 0 ? `In totale ti devono <b style="color:var(--green)">${eur(tot)}</b>.` : `In totale devi <b style="color:var(--red)">${eur(-tot)}</b>.`) : 'Cene, viaggi, affitto: chi ha pagato cosa e chi deve quanto a chi.'}</p><div style="margin-bottom:14px">${tabs}</div>
      ${S.split.length ? `<div class="grid cols-2">${S.split.map(g => { const me = Split.me(g); return `<button class="card sp-card" data-grp="${g.id}"><span class="sp-emoji">${esc(g.emoji || '👥')}</span><span class="grow" style="min-width:0"><b>${esc(g.name)}</b><small class="muted">${g.members.length} persone · ${(g.exp || []).filter(e => !e.pay).length} spese</small></span><span style="text-align:right"><b class="tnum" style="color:${me > 0.004 ? 'var(--green)' : me < -0.004 ? 'var(--red)' : 'var(--label-2)'}">${Math.abs(me) < 0.005 ? 'in pari' : eur(Math.abs(me))}</b><small class="muted" style="display:block">${me > 0.004 ? 'ti devono' : me < -0.004 ? 'devi' : ''}</small></span></button>`; }).join('')}</div>`
      : `<div class="card"><div class="empty">${ico('user')}<b>Nessun gruppo</b><p>Crea un gruppo (es. “Casa”, “Vacanza in Grecia”, “Cena di sabato”), aggiungi le persone e le spese: ti dico io chi deve cosa.</p><button class="btn primary" data-act="newGroup">Crea un gruppo</button></div></div>`}`;
  },
  mount(root) { wireSeg(root, 'spt', v => { UI.splitTab = v; App.render(); }); $$('[data-grp]', root).forEach(b => b.onclick = () => openGroup(b.dataset.grp)); $$('[data-loan]', root).forEach(b => b.onclick = () => editLoan(b.dataset.loan)); },
};
ACT.newGroup = () => editGroup();
