/* =========================================================
   DEBITI E CREDITI IN FINANZE — chi ti deve soldi e a chi li
   devi tu, persona per persona: prestiti (anche restituiti a
   rate o in parte) + i conti dei gruppi di spese divise.
   Movimenti sul conto facoltativi, promemoria su WhatsApp.
   ========================================================= */
const Debt = {
  rest(l) { if (l.kind === 'oggetto') return 0; const p = (l.parts || []).reduce((s, x) => s + (+x.amt || 0), 0); return Math.max(0, Math.round(((+l.amt || 0) - p) * 100) / 100); },
  open() { return S.loans.filter(l => !l.done && l.kind !== 'oggetto' && this.rest(l) > 0.004); },
  /** everything owed, grouped by person: + they owe me, − I owe them */
  people() {
    const P = {}, key = n => String(n || '?').trim().toLowerCase(), add = (name, v, item) => { const k = key(name); (P[k] ||= { name: String(name).trim(), net: 0, items: [] }); P[k].net += v; P[k].items.push(item); };
    for (const l of this.open()) add(l.who, l.dir === 'out' ? this.rest(l) : -this.rest(l), { t: 'loan', l });
    for (const g of S.split || []) for (const t of Split.settle(g)) { if (t.to === 'me') add(Split.name(g, t.from), t.amt, { t: 'grp', g, amt: t.amt }); else if (t.from === 'me') add(Split.name(g, t.to), -t.amt, { t: 'grp', g, amt: -t.amt }); }
    return Object.values(P).map(p => ({ ...p, net: Math.round(p.net * 100) / 100 })).filter(p => Math.abs(p.net) > 0.004 || p.items.length).sort((a, b) => Math.abs(b.net) - Math.abs(a.net));
  },
  totals() { let mine = 0, theirs = 0; for (const p of this.people()) { if (p.net > 0) mine += p.net; else theirs -= p.net; } return { mine, theirs }; },
  phone(name) { const c = (S.contacts || []).find(x => Contacts.name(x).toLowerCase() === String(name).toLowerCase()); return c && c.phone; },
  tx(l, amt, note) { Fin.ensure(); const t = { id: uid(), date: todayK(), amt: Math.round(amt * 100) / 100, cat: amt > 0 ? 'altro_in' : 'altro', note, wallet: l.wallet && S.money.wallets.some(w => w.id === l.wallet) ? l.wallet : S.money.defWallet, created: Date.now(), loan: l.id }; S.money.tx.push(t); save('money'); return t; },
  repay(l, amt) {
    amt = Math.min(this.rest(l), Math.abs(+amt || 0)); if (!amt) return;
    (l.parts ||= []).push({ d: todayK(), amt }); if (this.rest(l) < 0.005) { l.done = true; l.back = todayK(); }
    if (l.money) this.tx(l, l.dir === 'out' ? amt : -amt, `${l.dir === 'out' ? 'Restituiti da' : 'Restituiti a'} ${l.who}${l.what ? ' · ' + l.what : ''}`);
    save('loans'); if (l.done) Sound.done();
  },
};
