TITLES.home = 'Casa'; TITLES.garage = 'Auto e moto'; TITLES.ids = 'Documenti personali';
const hnum = v => typeof mnum === 'function' ? mnum(v) : parseFloat(String(v || '').replace(',', '.')) || 0;
const daysTo = k => k ? dayDiff(todayK(), k) : null;
const expLbl = k => { const n = daysTo(k); return n == null ? '' : n < 0 ? `scaduto da ${-n} g` : n === 0 ? 'scade oggi' : n === 1 ? 'scade domani' : n <= 30 ? `tra ${n} giorni` : fmtLong(k).replace(/^\S+ /, ''); };
