    const ps = $('#pnShop', root); if (ps) ps.onclick = () => { const recent = (S.shop || []).filter(x => x.done && (Date.now() - (x.doneAt || x.at || 0)) < 3 * 864e5); let n = 0; for (const x of recent) if (!S.pantry.some(p => p.name.toLowerCase() === x.name.toLowerCase() && p.added >= addDK(todayK(), -3))) { Pantry.add(x.name, { qty: x.qty }); n++; } Island.toast({ icon: 'check', c: 'var(--green)', t: `${n} cose in dispensa`, s: 'Con una scadenza stimata: correggila se serve', ms: 2400 }); App.render(); };
