/* ---------- cosa ti fa stare bene ---------- */
const MoodX = {
  rows(days = 60) { const out = []; for (let i = 1; i <= days; i++) { const k = addDK(todayK(), -i), e = S.journal.e[k]; if (!e || !e.m) continue; const H = (S.health && S.health.days[k]) || {}; out.push({ k, m: +e.m, sleep: H.sleep ? +H.sleep.h : null, sport: (H.burn || []).length > 0, steps: +H.steps || 0, focus: ((S.game.days || {})[k] || {}).focus || 0, ev: itemsOn(k).filter(x => !x.allDay).length, wd: dowIdx(k) }); } return out; },
  facts() {
    const R = this.rows(); if (R.length < 6) return null; const avg = L => L.length ? L.reduce((s, r) => s + r.m, 0) / L.length : null, out = [];
    const cmp = (label, A, B, a, b) => { const x = avg(A), y = avg(B); if (x != null && y != null && A.length >= 2 && B.length >= 2 && Math.abs(x - y) >= 0.3) out.push({ d: x - y, t: x > y ? `Stai meglio ${a} (${x.toFixed(1)} contro ${y.toFixed(1)})` : `Stai meglio ${b} (${y.toFixed(1)} contro ${x.toFixed(1)})`, label }); };
    cmp('sonno', R.filter(r => r.sleep >= 7), R.filter(r => r.sleep != null && r.sleep < 7), 'quando dormi almeno 7 ore', 'quando dormi meno di 7 ore');
    cmp('sport', R.filter(r => r.sport), R.filter(r => !r.sport), 'nei giorni in cui ti alleni', 'nei giorni senza allenamento');
    cmp('passi', R.filter(r => r.steps >= 7000), R.filter(r => r.steps && r.steps < 7000), 'quando cammini di più (7000+ passi)', 'nei giorni con meno passi');
    cmp('focus', R.filter(r => r.focus >= 60), R.filter(r => r.focus < 60), 'quando fai almeno un\'ora di concentrazione', 'nei giorni più leggeri di studio');
    cmp('impegni', R.filter(r => r.ev >= 4), R.filter(r => r.ev <= 2), 'nelle giornate piene', 'nelle giornate con pochi impegni');
    const wd = Array.from({ length: 7 }, (_, i) => avg(R.filter(r => r.wd === i))), best = wd.indexOf(Math.max(...wd.filter(x => x != null))), worst = wd.indexOf(Math.min(...wd.filter(x => x != null)));
    return { n: R.length, avg: avg(R), out: out.sort((a, b) => Math.abs(b.d) - Math.abs(a.d)), best: wd[best] != null ? DOW[(best + 1) % 7] : null, worst: wd[worst] != null && worst !== best ? DOW[(worst + 1) % 7] : null };
  },
};
{ const oR = VIEWS.journal.render; VIEWS.journal.render = function () { const h = oR.call(this), F = MoodX.facts(); const card = F ? `<section class="card mx-card"><div class="card-h"><h3>Cosa ti fa stare bene</h3><span class="muted" style="font-size:13px">ultimi ${F.n} giorni con l'umore</span></div>${F.out.length ? `<div class="list flat" style="box-shadow:none;margin:0 -8px">${F.out.slice(0, 4).map(f => `<div class="row"><span style="font-size:20px">${{ sonno: '😴', sport: '🏃', passi: '👟', focus: '🎯', impegni: '📅' }[f.label]}</span><span class="grow t" style="font-size:15px">${f.t}</span></div>`).join('')}</div>` : '<p class="muted" style="margin:0;font-size:14px">Ancora nessuna differenza evidente: continua a segnare l\'umore.</p>'}${F.best ? `<p class="muted" style="margin:8px 0 0;font-size:13px">Il giorno migliore di solito è il <b>${F.best}</b>${F.worst ? `, il più difficile il <b>${F.worst}</b>` : ''}.</p>` : ''}</section>` : ''; if (!card) return h; const i = h.indexOf('</p>'); return i > 0 ? h.slice(0, i + 4) + card + h.slice(i + 4) : card + h; }; }

/* ---------- giornata pesante ---------- */
ACT.heavyDay = () => {
  const t = todayK(), open = S.tasks.filter(x => !x.done && x.due && x.due <= t).sort((a, b) => (b.prio || 0) - (a.prio || 0) || (a.due || '').localeCompare(b.due || '')), keep = new Set(open.slice(0, 3).map(x => x.id)), evs = itemsOn(t).filter(x => !x.allDay && x.s && x.kind === 'event');
  const sh = openSheet({ title: 'Giornata pesante', wide: true, left: { label: 'Annulla' }, right: { label: 'Alleggerisci', act: s => { let n = 0; for (const x of open) if (!keep.has(x.id)) { x.due = typeof Sleep !== 'undefined' && x.prio >= 2 ? addDK(t, 1) : addDK(t, x.prio >= 1 ? 2 : 4); x.time = null; n++; } save('tasks'); S.profile.heavy = t; save('profile'); s.close(); App.refresh(); Island.toast({ icon: 'check', c: 'var(--green)', t: 'Giornata alleggerita', s: n ? `${n} promemoria spostati nei prossimi giorni` : 'Hai già solo l\'essenziale', ms: 2600 }); } },
    body: `<p class="muted" style="margin:0">Respira. Tieni solo le 3 cose che contano oggi: il resto lo sposto io nei prossimi giorni (le più importanti a domani). Tocca per scegliere cosa tenere.</p>
      <div class="list">${open.map(x => `<button class="row" data-hv="${x.id}"><span class="check ${keep.has(x.id) ? 'on' : ''}"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg></span><span class="grow"><div class="t">${esc(x.title)}</div><div class="s">${x.due < t ? 'in ritardo' : 'oggi'}${x.prio ? ' · ' + '!'.repeat(x.prio) : ''}</div></span><span class="pill" data-hvl>${keep.has(x.id) ? 'Oggi' : 'Sposto'}</span></button>`).join('') || '<div class="row"><span class="muted">Nessun promemoria per oggi 🎉</span></div>'}</div>
      ${evs.length ? `<div class="section-h" style="margin:4px 0 0">Impegni di oggi</div><div class="list">${evs.map(e => `<div class="row"><span class="tnum muted" style="width:46px">${e.s}</span><span class="grow t">${esc(e.title)}</span>${e.ev ? `<button class="btn sm plain" data-hvs="${e.id}">Rimanda</button>` : ''}</div>`).join('')}</div>` : ''}
      <button class="btn plain" id="hvF" style="align-self:flex-start">${ico('timer', 'sm')}Dopo, 25 minuti di concentrazione sulla prima</button>`,
    onMount(el) { $$('[data-hv]', el).forEach(b => b.onclick = () => { const id = b.dataset.hv; keep.has(id) ? keep.delete(id) : keep.add(id); b.querySelector('.check').classList.toggle('on', keep.has(id)); $('[data-hvl]', b).textContent = keep.has(id) ? 'Oggi' : 'Sposto'; });
      $$('[data-hvs]', el).forEach(b => b.onclick = () => { if (typeof ACT.snooze === 'function') ACT.snooze({ dataset: { id: b.dataset.hvs, kind: 'event' } }); else { const e = S.events.find(x => x.id === b.dataset.hvs); if (e) editEvent(e.id); } });
      $('#hvF', el).onclick = () => { $('[data-sh=right]', el.closest('.sheet') || el).click(); setTimeout(() => ACT.startFocus(), 400); }; } });
  return sh;
};
{ const oA = VIEWS.today.actions; VIEWS.today.actions = () => `<button class="btn sm" data-act="heavyDay" title="Oggi è troppo: tieni solo l'essenziale">😮‍💨<span class="hide-narrow">Giornata pesante</span></button>` + oA(); }

/* ---------- blocchi di tempo per la settimana ---------- */
ACT.planWeek = () => {
  const P = typeof Brief !== 'undefined' ? Brief.P() : { from: '09:00', to: '19:00' }, t = todayK(), days = Array.from({ length: 7 }, (_, i) => addDK(t, i));
  const cand = S.tasks.filter(x => !x.done && !x.time && (!x.due || x.due <= addDK(t, 6))).sort((a, b) => (a.due || '9').localeCompare(b.due || '9') || (b.prio || 0) - (a.prio || 0)).slice(0, 30);
  const plan = () => { const used = {}, out = []; for (const x of cand) { const min = +x.est || 45, start = x.due && x.due > t ? days.indexOf(x.due) : 0, order = [...days.slice(0, Math.max(1, (x.due ? days.indexOf(x.due) : 6) + 1))].map((k, i) => [k, i]); let placed = null;
      for (const [k] of (order.length ? order : [[t, 0]]).filter(([d]) => !(S.profile.heavy === t && d === t))) { const sl = freeSlots(k, P.from, P.to, used[k] || []).find(([a, b]) => b - a >= min); if (sl) { const a = Math.ceil(sl[0] / 15) * 15; if (a + min <= sl[1]) { placed = { k, a }; (used[k] ||= []).push([a, a + min + 10]); break; } } }
      out.push({ x, min, at: placed }); } return out; };
  let R = plan();
  const sh = openSheet({ title: 'Blocchi di tempo · 7 giorni', wide: true, left: { label: 'Annulla' }, right: { label: 'Metti in agenda', act: s => { let n = 0; for (const r of R) if (r.at && r.on !== false) { r.x.due = r.at.k; r.x.time = m2hm(r.at.a); r.x.est = r.min; n++; } save('tasks'); s.close(); App.refresh(); Island.toast({ icon: 'cal', c: 'var(--green)', t: `${n} blocchi in agenda`, s: 'Li vedi nel Calendario: trascinali se vuoi spostarli', ms: 2600 }); } },
    body: `<p class="muted" style="margin:0">Ho messo ogni promemoria nel primo spazio libero prima della sua scadenza (orario ${P.from}–${P.to}). Cambia la durata o togli quelli che non vuoi.</p><div id="pwL"></div>` });
  const paint = () => { const by = {}; for (const r of R) (by[r.at ? r.at.k : 'none'] ||= []).push(r);
    $('#pwL', sh.el).innerHTML = [...days, 'none'].filter(k => by[k]).map(k => `<div class="section-h">${k === 'none' ? 'Non c\'è spazio' : relDay(k, true)}</div><div class="list">${by[k].sort((a, b) => (a.at ? a.at.a : 0) - (b.at ? b.at.a : 0)).map(r => `<div class="row"><button class="check ${r.on !== false && r.at ? 'on' : ''}" data-pwo="${r.x.id}"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg></button><span class="tnum" style="width:92px;color:var(--accent)">${r.at ? `${m2hm(r.at.a)}–${m2hm(r.at.a + r.min)}` : '—'}</span><span class="grow t">${esc(r.x.title)}</span><select class="input" data-pwm="${r.x.id}" style="width:auto">${[15, 30, 45, 60, 90, 120, 180].map(m => `<option value="${m}" ${m === r.min ? 'selected' : ''}>${m < 60 ? m + ' min' : m / 60 + ' h'}</option>`).join('')}</select></div>`).join('')}</div>`).join('') || '<p class="muted">Nessun promemoria senza orario nei prossimi 7 giorni.</p>';
    $$('[data-pwo]', sh.el).forEach(b => b.onclick = () => { const r = R.find(z => z.x.id === b.dataset.pwo); r.on = r.on === false; paint(); });
    $$('[data-pwm]', sh.el).forEach(s => s.onchange = () => { cand.find(z => z.id === s.dataset.pwm).est = +s.value; const off = new Set(R.filter(z => z.on === false).map(z => z.x.id)); R = plan(); R.forEach(z => { if (off.has(z.x.id)) z.on = false; }); paint(); }); };
  paint(); return sh;
};
{ const oA = VIEWS.tasks.actions; VIEWS.tasks.actions = () => `<button class="btn sm" data-act="tplOpen" title="Modelli pronti">${ico('copy', 'sm')}<span class="hide-narrow">Modelli</span></button><button class="btn sm" data-act="planWeek" title="Metti i promemoria nell'agenda della settimana">${ico('cal', 'sm')}<span class="hide-narrow">Blocchi di tempo</span></button>` + oA(); }

