/* ---------- studio insieme (pomodoro di gruppo) ---------- */
if (typeof SKIND !== 'undefined') SKIND.focus = ['Studio insieme', '⏱️', 'var(--orange)'];
const GroupFocus = {
  live(v) { return v.run && v.run.start + v.run.min * 60e3 > Date.now() ? v.run : null; },
  join(sp) { const r = this.live(sp.v); if (!r) return; const left = Math.round((r.start + r.min * 60e3 - Date.now()) / 1000); if (left < 30) return; Timer.set && Timer.set('focus', false); Timer.mode = 'focus'; Timer.dur = left; Timer.left = left; Timer.paused = false; Timer.start('focus'); Timer.left = left; Timer.endAt = Date.now() + left * 1000; Timer.persist && Timer.persist(); Share.mutate(sp.id, (v, me) => { (v.run ||= r).in ||= {}; if (v.run && v.run.start === r.start) v.run.in[me] = Date.now(); }).catch(() => {}); Island.toast({ icon: 'timer', c: 'var(--orange)', t: 'Studi insieme a loro', s: `${Math.round(left / 60)} minuti`, ms: 2200 }); },
};
if (typeof Share !== 'undefined') {
  const oD = Share.diffNews.bind(Share); Share.diffNews = function (h, a, b, me) { if (h.kind !== 'focus') return oD(h, a, b, me); const r = b.run, o = a.run; if (r && (!o || o.start !== r.start) && r.by !== me && r.start + r.min * 60e3 > Date.now()) { const nm = (b.names || {})[r.by] || String(r.by).split('@')[0]; return [{ id: h.id, t: `${cap(nm)} ha iniziato a studiare (${r.min} min)`, s: `${h.name}${r.label ? ' · ' + r.label : ''} — tocca Apri per unirti` }]; } return []; };
  const oO = openSpace; openSpace = function (id) { const sp0 = Share.spaces.find(x => x.id === id); if (!sp0 || sp0.kind !== 'focus') return oO(id);
    const sh = openSheet({ title: `⏱️ ${sp0.name}`, wide: true, right: { label: 'Persone', primary: false, act: () => peopleSheet(id) }, body: `<div id="gfB" style="display:flex;flex-direction:column;gap:12px"></div>`, onClose() { clearInterval(sh._t); sh._space = null; } }); sh._space = id;
    const paint = sh._paint = () => { const sp = Share.spaces.find(x => x.id === id); if (!sp) return sh.close(); const v = sp.v || {}, r = GroupFocus.live(v), N = v.names || {}, me = Share.email(), B = $('#gfB', sh.el), left = r ? Math.max(0, Math.round((r.start + r.min * 60e3 - Date.now()) / 1000)) : 0, ppl = Object.keys((r && r.in) || {});
      B.innerHTML = r ? `<div class="gf-live"><small>${esc(N[r.by] || r.by.split('@')[0])} ha avviato${r.label ? ' · ' + esc(r.label) : ''}</small><b class="tnum" id="gfT">${Math.floor(left / 60)}:${pad(left % 60)}</b><div class="sh-ppl" style="justify-content:center">${ppl.map(e => avatar(e, N, 30)).join('')}</div><small>${ppl.length} ${ppl.length === 1 ? 'persona sta' : 'persone stanno'} studiando</small></div>${ppl.includes(me) ? '<p class="muted" style="text-align:center;margin:0">Sei dentro: il tuo timer è sincronizzato.</p>' : `<button class="btn primary" id="gfJ" style="align-self:center">${ico('play', 'sm')}Unisciti</button>`}`
        : `<p class="muted" style="margin:0">Avvia un pomodoro per tutto il gruppo: gli altri ricevono l'avviso e si uniscono con un tocco. Vince chi resiste fino alla fine 💪</p><input class="input" id="gfL" placeholder="Su cosa (es. Capitolo 4 di Fisica)"><div style="display:flex;gap:8px;flex-wrap:wrap">${[25, 50, 90].map(m => `<button class="btn ${m === 25 ? 'primary' : ''}" data-gfm="${m}">${ico('timer', 'sm')}${m} min per tutti</button>`).join('')}</div>`;
      const j = $('#gfJ', B); if (j) j.onclick = () => { GroupFocus.join(sp); setTimeout(paint, 600); };
      $$('[data-gfm]', B).forEach(b => b.onclick = async () => { const min = +b.dataset.gfm, lbl = ($('#gfL', B).value || '').trim(); try { await Share.mutate(id, (v2, me2) => { v2.run = { start: Date.now(), min, by: me2, label: lbl, in: { [me2]: Date.now() } }; }); Timer.mode = 'focus'; Timer.dur = min * 60; Timer.left = min * 60; Timer.paused = false; Timer.start('focus'); paint(); } catch (e) { Island.toast({ icon: 'x', c: 'var(--red)', t: 'Non riuscito', s: String(e.message).slice(0, 100), ms: 2600 }); } }); };
    paint(); clearInterval(sh._t); sh._t = setInterval(() => { const t = $('#gfT', sh.el), sp = Share.spaces.find(x => x.id === id), r = sp && GroupFocus.live(sp.v); if (t && r) { const l = Math.max(0, Math.round((r.start + r.min * 60e3 - Date.now()) / 1000)); t.textContent = `${Math.floor(l / 60)}:${pad(l % 60)}`; } else if (t) paint(); }, 1000); Share.pull(true); return sh; };
}
{ const oA = VIEWS.focus && VIEWS.focus.actions; if (VIEWS.focus) VIEWS.focus.actions = () => `<button class="btn sm" data-act="groupFocus">${ico('share', 'sm')}<span class="hide-narrow">Studia con gli altri</span></button>` + (oA ? oA() : ''); }
