/* ---------- esporta tutto in Excel ---------- */
const XL = { LIB: 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js', async lib() { if (!window.XLSX) await loadScript(this.LIB); if (!window.XLSX) throw new Error('lib'); return window.XLSX; } };
const dIt = k => k ? String(k).split('-').reverse().join('/') : '';
ACT.exportXlsx = async () => {
  let X; try { X = await XL.lib(); } catch (_) { Island.toast({ icon: 'x', c: 'var(--red)', t: 'Serve la connessione', s: 'Per creare il file Excel la prima volta', ms: 2600 }); return; }
  Fin.ensure(); const wb = X.utils.book_new(), add = (name, rows) => { if (!rows.length) return; const ws = X.utils.json_to_sheet(rows); ws['!cols'] = Object.keys(rows[0]).map(k => ({ wch: Math.min(48, Math.max(10, k.length + 2, ...rows.slice(0, 200).map(r => String(r[k] ?? '').length))) })); X.utils.book_append_sheet(wb, ws, name.slice(0, 31)); };
  add('Movimenti', S.money.tx.slice().sort((a, b) => b.date.localeCompare(a.date)).map(t => ({ Data: dIt(t.date), Descrizione: t.note || '', Categoria: t.type === 'transfer' ? 'Trasferimento' : mcatOf(t.cat, t.amt > 0)[0], Conto: (Fin.wallet(Fin.wid(t)) || {}).name || '', Importo: Math.round(t.amt * 100) / 100, Note: [t.rcpt ? 'scontrino' : '', t.loan ? 'prestito' : '', t.inst ? 'rata' : '', t.split ? 'spesa divisa' : ''].filter(Boolean).join(', ') })));
  if (typeof Inst !== 'undefined') add('Rate', S.inst.map(p => ({ Nome: p.name, Ente: p.who || '', Rata: p.amt, 'N. rate': p.n, Pagate: Inst.paid(p), 'Da pagare': Inst.rest(p), 'Prossima': Inst.next(p) ? dIt(Inst.next(p).date) : 'finite', Interessi: Inst.interest(p) ?? '' })));
  if (typeof Debt !== 'undefined') add('Debiti e crediti', S.loans.filter(l => l.kind !== 'oggetto').map(l => ({ Persona: l.who, Tipo: l.dir === 'out' ? 'Mi deve' : 'Devo', Importo: l.amt, Residuo: Debt.rest(l), Per: l.what || '', Data: dIt(l.date), Scadenza: dIt(l.due), Stato: l.done ? 'saldato' : 'aperto' })));
  add('Abbonamenti', (S.money.subs || []).map(x => ({ Nome: x.name, Importo: x.amt, Frequenza: x.every || x.freq || '', 'Al mese': Math.round(Fin.monthly(x) * 100) / 100 })));
  if (S.hours && S.hours.entries) add('Ore lavorate', S.hours.entries.slice().sort((a, b) => b.date.localeCompare(a.date)).map(e => ({ Data: dIt(e.date), Cliente: (S.hours.clients.find(c => c.id === e.client) || {}).name || '', Ore: Math.round(e.min / 6) / 10, Note: e.note || '', Fatturato: e.billed ? 'sì' : 'no', Pagato: e.paid ? 'sì' : 'no' })));
  add('Esami', (S.exams || []).map(e => ({ Esame: e.name, CFU: e.cfu, Voto: e.lode ? '30L' : e.grade || '', Data: dIt(e.date), Stato: e.status === 'passed' ? 'superato' : e.status === 'idoneo' ? 'idoneo' : 'da sostenere' })));
  if (S.health) add('Salute', Object.entries(S.health.days).sort((a, b) => b[0].localeCompare(a[0])).slice(0, 730).map(([k, d]) => { const E = typeof Health !== 'undefined' ? Health.eaten(k) : { kcal: '' }; return { Data: dIt(k), 'Kcal mangiate': E.kcal || '', Passi: d.steps || '', Allenamenti: (d.burn || []).length || '', 'Ore di sonno': d.sleep ? d.sleep.h : '', Acqua_ml: d.water || '' }; }).filter(r => r['Kcal mangiate'] || r.Passi || r.Allenamenti || r['Ore di sonno']));
  if (S.health && S.health.weights) add('Peso', S.health.weights.slice().sort((a, b) => b.d.localeCompare(a.d)).map(w => ({ Data: dIt(w.d), Kg: w.kg })));
  add('Promemoria', S.tasks.map(t => ({ Titolo: t.title, Scadenza: dIt(t.due), Ora: t.time || '', Priorità: t.prio || 0, Fatto: t.done ? 'sì' : 'no' })));
  add('Abitudini', S.habits.map(h => ({ Abitudine: h.name, 'Giorni totali': Object.keys(h.days).length, 'Ultimi 30 giorni': Object.keys(h.days).filter(k => k >= addDK(todayK(), -30)).length })));
  if (S.dues) add('Scadenze', S.dues.map(d => ({ Nome: d.name, Data: dIt(d.date), Importo: d.amt || '', Ripete: +d.rep ? `ogni ${d.rep} mesi` : 'no', Stato: d.paid ? 'fatto' : 'da fare' })));
  if (S.vehicles) for (const v of S.vehicles) add(`Auto ${v.name}`, [...(v.fuel || []).map(f => ({ Data: dIt(f.d), Tipo: 'Rifornimento', Km: f.km, Euro: f.eur, Litri: f.liters || '' })), ...(v.serv || []).map(s => ({ Data: dIt(s.d), Tipo: s.what, Km: s.km, Euro: s.eur || '', Litri: '' }))].sort((a, b) => String(b.Data.split('/').reverse().join('')).localeCompare(a.Data.split('/').reverse().join(''))));
  if (!wb.SheetNames.length) { Island.toast({ icon: 'download', t: 'Niente da esportare, per ora', ms: 2000 }); return; }
  const buf = X.write(wb, { bookType: 'xlsx', type: 'array' }); await saveBlob(new Blob([buf], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }), `Orbita-${todayK()}.xlsx`);
};
Promise.resolve().then(() => { const oR = VIEWS.settings.render, oM = VIEWS.settings.mount;
  VIEWS.settings.render = function () { const h = oR.call(this), sec = `<div class="section-h">I tuoi dati</div><div class="list flat"><button class="row" data-act="exportXlsx"><span class="tile-ico" style="background:var(--green)">${ico('download')}</span><span class="grow"><div class="t">Esporta tutto in Excel</div><div class="s">Movimenti, rate, debiti, ore, esami, salute, promemoria, scadenze, auto: un foglio per ognuno</div></span>${ico('right', 'sm chev')}</button><div class="row"><span class="tile-ico" style="background:var(--indigo)">${ico('grid')}</span><span class="grow"><div class="t">Riepilogo della settimana</div><div class="s">La domenica sera, come notifica (anche a Orbita chiuso)</div></span>${toggleBtn('wsOn', S.profile.weekSum !== false)}</div></div>`, mk = '<div class="section-h">Avvisi e notifiche', i = h.indexOf(mk); return i >= 0 ? h.slice(0, i) + sec + h.slice(i) : h + sec; };
  VIEWS.settings.mount = function (root) { oM && oM.call(this, root); const w = $('#wsOn', root); if (w) wireToggle(w, on => { S.profile.weekSum = on; save('profile'); Alerts.sync && Alerts.sync(); }); }; });
Promise.resolve().then(() => { if (typeof Assistant === 'undefined') return; const oT = Assistant.tools.bind(Assistant); Assistant.tools = function () { const self = this; return oT().concat([
  { name: 'add_place_reminder', description: 'Aggiunge un promemoria da mostrare quando l\'utente arriva in un luogo (supermercato, casa, università, lavoro, palestra…).', inputSchema: { type: 'object', properties: { place: { type: 'string' }, text: { type: 'string' } }, required: ['place', 'text'] }, execute(i) { const q = String(i.place).toLowerCase(); let p = S.places.find(x => x.name.toLowerCase() === q) || S.places.find(x => x.name.toLowerCase().includes(q) || q.includes(x.name.toLowerCase())); if (!p) { p = { id: uid(), name: cap(String(i.place)), emoji: '📍', items: [] }; S.places.push(p); } (p.items ||= []).push({ id: uid(), t: String(i.text), done: false, at: Date.now() }); save('places'); Phone && Phone.queue && Phone.queue(); self.note('pin', 'Promemoria per ' + p.name); return { ok: true, luogo: p.name }; } },
  { name: 'week_summary', description: 'Riepilogo della settimana appena trascorsa (promemoria fatti, studio, spese, passi, allenamenti, abitudini).', inputSchema: { type: 'object', properties: {} }, execute() { return WeekSum.of(); } },
]); }; });

/* =========================================================
   ESPERIENZA — menu personalizzabile (ordine, nascondi,
   profili pronti), ricerca universale con comandi, benvenuto
   guidato, backup e ripristino con un file, Oggi riordinabile
   trascinando, notifiche più intelligenti (ore tranquille e
   riepilogo delle cose poco urgenti) e modalità esame.
   ========================================================= */

/* ---------- menu personalizzabile ---------- */
const NAVP = {
  studio: ['courses', 'exams', 'notes', 'boards', 'docs', 'thesis', 'lang'],
  lavoro: ['projects', 'hours', 'applies'],
  soldi: ['money', 'receipts', 'split', 'dues'],
  salute: ['health', 'meds', 'habits'],
  casa: ['shop', 'home', 'garage', 'ids', 'shared'],
  tempo: ['trips', 'journal', 'lists', 'recipes', 'parties', 'spots'],
  persone: ['messages', 'contacts'],
  crescita: ['year', 'review', 'goals', 'report', 'focus'],
};
const NAVA = { studio: ['🎓', 'Studio'], lavoro: ['💼', 'Lavoro'], soldi: ['💶', 'Soldi'], salute: ['💪', 'Salute e abitudini'], casa: ['🏠', 'Casa e documenti'], tempo: ['🎬', 'Tempo libero e viaggi'], persone: ['💬', 'Persone e messaggi'], crescita: ['🚀', 'Obiettivi e crescita'] };
{ const oNG = navGroups; navGroups = function () { const ord = S.profile.navOrder || []; return oNG().map(g => ({ ...g, items: g.items.slice().sort((a, b) => { const x = ord.indexOf(a[0]), y = ord.indexOf(b[0]); return (x < 0 ? 999 : x) - (y < 0 ? 999 : y); }) })); }; }
ACT.navEdit = () => {
  const all = NAV.map(g => ({ g: g.g, items: g.items.filter(([id]) => id !== 'today') })), P = S.profile; let hid = new Set(P.hidden || []), ord = [...(P.navOrder || [])];
  const sh = openSheet({ title: 'Personalizza il menu', wide: true, left: { label: 'Annulla' }, right: { label: 'Fine', act: s => { P.hidden = [...hid]; P.navOrder = ord; save('profile'); s.close(); App.render(); } }, body: `<div id="neB" style="display:flex;flex-direction:column;gap:12px"></div>` });
  const paint = () => { const B = $('#neB', sh.el), sortG = items => items.slice().sort((a, b) => { const x = ord.indexOf(a[0]), y = ord.indexOf(b[0]); return (x < 0 ? 999 : x) - (y < 0 ? 999 : y); });
    B.innerHTML = `<p class="muted" style="margin:0">Spegni quello che non usi e metti in alto quello che usi di più. Le sezioni nascoste restano raggiungibili dalla ricerca (⌘K o Ctrl+K).</p>
      <div class="chips"><button class="chip" data-np="all">Tutto acceso</button>${Object.entries(NAVA).map(([k, [e, n]]) => `<button class="chip" data-np="${k}">${e} Solo ${n.toLowerCase()}</button>`).join('')}</div>
      ${all.map(g => `<div class="section-h" style="margin:4px 0 0">${esc(g.g || 'In alto')}</div><div class="list">${sortG(g.items).map(([id, n, i], j, A) => `<div class="row"><span class="tile-ico" style="background:${hid.has(id) ? 'var(--gray)' : 'var(--accent)'}">${ico(i)}</span><span class="grow t" style="${hid.has(id) ? 'color:var(--label-3)' : ''}">${esc(n)}</span><button class="icon-btn" data-nu="${id}" ${j ? '' : 'disabled'} aria-label="Su">${ico('left', 'sm').replace('ico sm', 'ico sm rot90')}</button><button class="icon-btn" data-nd="${id}" ${j < A.length - 1 ? '' : 'disabled'} aria-label="Giù">${ico('right', 'sm').replace('ico sm', 'ico sm rot90')}</button>${toggleBtn('nt_' + id, !hid.has(id))}</div>`).join('')}</div>`).join('')}`;
    $$('[data-np]', B).forEach(b => b.onclick = () => { const k = b.dataset.np; if (k === 'all') hid = new Set(); else { const keep = new Set(['assistant', 'calendar', 'tasks', 'settings', 'account', ...NAVP[k]]); hid = new Set(all.flatMap(g => g.items.map(x => x[0])).filter(id => !keep.has(id))); } paint(); });
    all.forEach(g => g.items.forEach(([id]) => { const t = $('#nt_' + id, B); if (t) wireToggle(t, on => { on ? hid.delete(id) : hid.add(id); paint(); }); }));
    const move = (id, d) => { const g = all.find(x => x.items.some(i => i[0] === id)), L = sortG(g.items).map(x => x[0]), i = L.indexOf(id), j = i + d; if (j < 0 || j >= L.length) return; [L[i], L[j]] = [L[j], L[i]]; ord = [...ord.filter(x => !L.includes(x)), ...L]; paint(); };
    $$('[data-nu]', B).forEach(b => b.onclick = () => move(b.dataset.nu, -1)); $$('[data-nd]', B).forEach(b => b.onclick = () => move(b.dataset.nd, 1)); };
  paint(); return sh;
};
/* a small “Personalizza” link at the bottom of the sidebar */
{ const oRC = App.refreshChrome.bind(App); App.refreshChrome = function () { const r = oRC(); try { const sb = $('#sidebar'), foot = sb && $('.side-foot', sb); if (sb && !$('#navEditBtn', sb)) { const b = document.createElement('button'); b.id = 'navEditBtn'; b.className = 'nav-edit'; b.dataset.act = 'navEdit'; b.innerHTML = `${ico('gear', 'sm')}<span>Personalizza il menu</span>`; foot ? sb.insertBefore(b, foot) : sb.appendChild(b); } } catch (_) {} return r; }; }

/* ---------- ricerca universale + comandi ---------- */
const CMD_ACT = [
  ['Nuova rata', 'bank', () => { go('money'); editInst(); }], ['Mi devono dei soldi', 'wallet', () => newDebt('out')], ['Devo dei soldi', 'wallet', () => newDebt('in')], ['Nuovo salvadanaio', 'wallet', () => jarSheet()], ['Spese detraibili (730)', 'receipt', () => ACT.tax730()],
  ['Scansiona un documento', 'scan', () => ACT.docScan()], ['Scansiona uno scontrino', 'receipt', () => ACT.receiptScan()], ['Apri la dispensa', 'grid', () => { UI.homeTab = 'pantry'; go('home'); }], ['Dispensa da foto', 'image', () => ACT.pantryPhoto()],
  ['Interrogami', 'mic', () => oralExam()], ['Mappa concettuale', 'shape', () => ACT.mapFromText()], ['Giornata pesante', 'today', () => ACT.heavyDay()], ['Blocchi di tempo della settimana', 'cal', () => ACT.planWeek()], ['Modelli pronti', 'copy', () => ACT.tplOpen()],
  ['Revisione settimanale', 'checklist', () => reviewWizard()], ['Obiettivo dell\'anno', 'flag', () => editYGoal()], ['Routine del mattino', 'sun', () => routinePlay('am')], ['Routine della sera', 'moon', () => routinePlay('pm')],
  ['Rifornimento', 'car', () => { go('garage'); if (S.vehicles[0]) vehFuel(S.vehicles[0].id); }], ['Nuova ricetta', 'chef', () => recImport()], ['Cosa cucino?', 'chef', () => ACT.recIdeas()], ['Aggiungi film, serie o libro', 'film', () => mediaSearch(UI.mType || 'movie')],
  ['Promemoria per luogo', 'pin', () => ACT.places()], ['Esporta tutto in Excel', 'download', () => ACT.exportXlsx()], ['Fai un backup', 'download', () => ACT.exportData()], ['Personalizza il menu', 'gear', () => ACT.navEdit()], ['Modalità esame', 'grad', () => ExamMode.toggle(true)],
  ['Nuova bolletta', 'receipt', () => ACT.billScan()], ['Tesi', 'book', () => go('thesis')], ['Parole del giorno', 'cards', () => ACT.langToday()], ['Allenati con una scheda', 'flame', () => ACT.gymPlans()], ['Scrivi con l\'AI', 'pen', () => go('write')],
];
const CMD_SRC = [
  q => (S.recipes || []).filter(r => (r.title + ' ' + (r.ingredients || []).map(i => i.name).join(' ')).toLowerCase().includes(q)).slice(0, 5).map(r => ({ sec: 'Ricette', t: r.title, s: (r.ingredients || []).slice(0, 4).map(i => i.name).join(', '), i: 'chef', fn: () => openRecipe(r.id) })),
  q => (S.media || []).filter(m => (m.title + ' ' + (m.creator || '')).toLowerCase().includes(q)).slice(0, 5).map(m => ({ sec: 'Film, serie e libri', t: m.title, s: `${MTYPE[m.type][0]} · ${m.status === 'done' ? MTYPE[m.type][5] : m.status === 'doing' ? 'in corso' : MTYPE[m.type][3]}`, i: 'film', fn: () => openMedia(m.id) })),
  q => (S.contacts || []).filter(c => (Contacts.name(c) + ' ' + (c.phone || '') + ' ' + (c.email || '') + ' ' + (c.org || '')).toLowerCase().includes(q)).slice(0, 5).map(c => ({ sec: 'Rubrica', t: Contacts.name(c), s: c.phone || c.email || '', i: 'user', fn: () => { go('contacts'); openContact(c.id); } })),
  q => S.money.tx.filter(t => (t.note || '').toLowerCase().includes(q)).sort((a, b) => b.date.localeCompare(a.date)).slice(0, 5).map(t => ({ sec: 'Movimenti', t: `${t.note} · ${eur(t.amt)}`, s: relDay(t.date, true), i: 'wallet', fn: () => { go('money'); editTx(t.id); } })),
  q => (S.dues || []).filter(d => d.name.toLowerCase().includes(q)).slice(0, 4).map(d => ({ sec: 'Scadenze', t: d.name, s: relDay(d.date, true), i: 'clock', fn: () => editDue(d.id) })),
  q => (S.pantry || []).filter(p => p.name.toLowerCase().includes(q)).slice(0, 4).map(p => ({ sec: 'Dispensa', t: p.name, s: p.exp ? expLbl(p.exp) : '', i: 'grid', fn: () => { UI.homeTab = 'pantry'; go('home'); } })),
  q => (S.shop || []).filter(x => !x.done && x.name.toLowerCase().includes(q)).slice(0, 3).map(x => ({ sec: 'Spesa', t: x.name, s: 'nella lista', i: 'list', fn: () => go('shop') })),
  q => (S.ids || []).filter(d => (d.name + ' ' + (d.num || '')).toLowerCase().includes(q)).slice(0, 3).map(d => ({ sec: 'Documenti personali', t: d.name, s: d.exp ? 'scade ' + relDay(d.exp, true).toLowerCase() : '', i: 'lock', fn: () => { go('ids'); idOpen(d.id); } })),
  q => (S.inst || []).filter(p => (p.name + ' ' + (p.who || '')).toLowerCase().includes(q)).slice(0, 3).map(p => ({ sec: 'Rate', t: p.name, s: Inst.next(p) ? `prossima ${relDay(Inst.next(p).date, true).toLowerCase()} · ${eur(Inst.next(p).amt)}` : 'pagate', i: 'bank', fn: () => openInst(p.id) })),
  q => (S.loans || []).filter(l => (l.who + ' ' + (l.what || '')).toLowerCase().includes(q) && !l.done).slice(0, 3).map(l => ({ sec: 'Debiti e crediti', t: `${l.who}${l.what ? ' · ' + l.what : ''}`, s: l.dir === 'out' ? 'ti deve' : 'devi', i: 'wallet', fn: () => personSheet(l.who) })),
  q => (S.vehicles || []).filter(v => (v.name + ' ' + (v.plate || '')).toLowerCase().includes(q)).map(v => ({ sec: 'Auto e moto', t: v.name, s: `${Veh.km(v).toLocaleString('it-IT')} km`, i: 'car', fn: () => go('garage') })),
  q => (S.ygoals || []).filter(g => g.title.toLowerCase().includes(q)).slice(0, 3).map(g => ({ sec: 'Obiettivi dell\'anno', t: g.title, s: `${Math.round(YG.prog(g) * 100)}%`, i: 'flag', fn: () => { go('year'); openYGoal(g.id); } })),
  q => (S.bills || []).filter(b => (b.provider + ' ' + b.kind).toLowerCase().includes(q)).slice(0, 3).map(b => ({ sec: 'Bollette', t: `${(BKIND[b.kind] || BKIND.altro)[0]} ${b.provider || ''}`, s: `${eur(b.amt)} · ${relDay(b.due || b.to || todayK(), true)}`, i: 'receipt', fn: () => billOpen(b.id) })),
];

/* ---------- benvenuto guidato ---------- */
function onboarding(force) {
  let name = S.profile.name || '', areas = new Set(S.profile.areas || ['studio', 'soldi', 'salute']);
  const sh = openSheet({ title: 'Configuriamo Orbita', wide: true, left: { label: force ? 'Annulla' : 'Più tardi' }, right: { label: 'Fatto', act: s => { S.profile.name = $('#obN', s.el).value.trim() || S.profile.name; S.profile.areas = [...areas]; const keep = new Set(['today', 'calendar', 'tasks', 'assistant', 'write', ...[...areas].flatMap(a => NAVP[a] || [])]); S.profile.hidden = NAV.flatMap(g => g.items.map(x => x[0])).filter(id => !keep.has(id)); S.profile.onboarded = true; S.profile.navTold = true; save('profile'); s.close(); App.render(); confetti(80); Island.toast({ icon: 'spark', c: 'var(--accent)', t: `Pronto${S.profile.name ? ', ' + S.profile.name : ''}!`, s: 'Puoi cambiare tutto in “Personalizza il menu”', ms: 3000 }); } },
    body: `<p class="muted" style="margin:0">Due domande e Orbita mostra solo quello che ti serve. Il resto resta disponibile: lo riaccendi quando vuoi.</p>
      <div class="field"><label for="obN">Come ti chiami?</label><input class="input" id="obN" value="${esc(name)}" placeholder="Il tuo nome"></div>
      <div class="field"><span class="lbl">Per cosa la userai?</span><div class="ob-grid">${Object.entries(NAVA).map(([k, [e, n]]) => `<button type="button" class="ob-tile" data-ob="${k}" aria-pressed="${areas.has(k)}"><span>${e}</span><b>${n}</b></button>`).join('')}</div></div>`,
    onMount(el) { $$('[data-ob]', el).forEach(b => b.onclick = () => { const k = b.dataset.ob; areas.has(k) ? areas.delete(k) : areas.add(k); b.setAttribute('aria-pressed', areas.has(k)); }); } });
  if (!force) { S.profile.obAsked = Date.now(); save('profile'); }
  return sh;
}
ACT.onboarding = () => onboarding(true);
