    for (const [at, L] of Object.entries(slots)) { if (L.length === 1) { keep.push({ ...L[0], at: +at }); continue; } const key = 'dg:' + L.map(a => a.key).sort().join('|').slice(0, 180); if (this.fired[key]) continue; keep.push({ key, at: +at, title: `🔔 ${L.length} cose da ricordare`, body: L.map(a => a.title.replace(/^\S+\s/, '')).slice(0, 4).join(' · '), view: L[0].view || 'today', parts: L.map(a => a.key) }); }
