  return `<p class="subtitle">Fotografa la bolletta: leggo importo, periodo, consumi e scadenza. Ti avviso prima che scada e ti dico se stai consumando più dell'anno scorso.</p>
    ${S.bills.length ? `<div class="inst-sum" style="margin-bottom:12px"><div><span class="muted">Da pagare</span><b class="tnum" style="color:${open.length ? 'var(--orange)' : 'var(--label)'}">${eur(open.reduce((s, b) => s + (+b.amt || 0), 0))}</b><small class="muted">${open.length} ${open.length === 1 ? 'bolletta' : 'bollette'}</small></div><div><span class="muted">Spese nel ${y}</span><b class="tnum">${eur(yr)}</b><small class="muted">tutte le utenze</small></div></div>
      ${open.length ? `<div class="list" style="margin-bottom:12px">${open.map(b => `<div class="row"><span class="inst-e">${BKIND[b.kind][1]}</span><span class="grow"><div class="t">${BKIND[b.kind][0]}${b.provider ? ' · ' + esc(b.provider) : ''}</div><div class="s" style="color:${expCol(b.due)}">scade ${relDay(b.due, true).toLowerCase()}</div></span><b class="tnum">${eur(b.amt)}</b><button class="btn sm primary" data-blp="${b.id}">${ico('check', 'sm')}Pagata</button></div>`).join('')}</div>` : ''}
      ${kinds.map(k => { const L = Bills.byKind(k), last = L[L.length - 1], yy = last && Bills.yoy(last); return `<section class="card" style="margin-bottom:12px"><div class="card-h"><h3>${BKIND[k][1]} ${BKIND[k][0]}</h3>${yy != null ? `<span class="pill c" style="--c:${yy > 0.05 ? 'var(--red)' : yy < -0.05 ? 'var(--green)' : 'var(--gray)'}">${yy > 0 ? '+' : ''}${Math.round(yy * 100)}% rispetto all'anno scorso</span>` : ''}</div>${chart(k)}${last && last.cons && BKIND[k][2] ? `<p class="muted" style="margin:6px 0 0;font-size:13px">Ultima: ${(+last.cons).toLocaleString('it-IT')} ${BKIND[k][2]}${Bills.perDay(last) ? ` · ${String(Math.round(Bills.perDay(last) * 10) / 10).replace('.', ',')} ${BKIND[k][2]} al giorno` : ''} · ${eur(last.amt)}</p>` : ''}</section>`; }).join('')}`
    : `<div class="card"><div class="empty"><span style="font-size:40px">🧾</span><b>Nessuna bolletta</b><p>Fotografa o carica il PDF di una bolletta di luce, gas, acqua o internet.</p><button class="btn primary" data-act="billScan">Aggiungi una bolletta</button></div></div>`}`;
