function billsMount(root) { $$('[data-blp]', root).forEach(b => b.onclick = () => { const x = S.bills.find(z => z.id === b.dataset.blp); Bills.pay(x); Sound.done(); App.render(); }); $$('[data-bl]', root).forEach(b => b.onclick = () => billOpen(b.dataset.bl)); }
