  plural(w) { const M = { vasetto: 'vasetti', fetta: 'fette', media: 'medie', medio: 'medi', grande: 'grandi', piccola: 'piccole', piccolo: 'piccoli', uovo: 'uova', pezzo: 'pezzi', bicchiere: 'bicchieri', tazza: 'tazze', panino: 'panini', frutto: 'frutti', scatoletta: 'scatolette', confezione: 'confezioni', spicchio: 'spicchi', foglia: 'foglie', bustina: 'bustine', porzione: 'porzioni', mela: 'mele', banana: 'banane', arancia: 'arance', pera: 'pere' }; return M[w] || w; },
