function dietDayHtml(D, di, done, ro) { const d = D.days[di]; if (!d) return '';
  return d.meals.map((m, mi) => { const keys = m.items.map((_, ii) => Diet.key(di, mi, ii)), all = done && keys.every(x => done.has(x)), kc = Math.round(m.items.reduce((a, it) => a + (+it.kcal || 0) * (+it.g || 0) / 100, 0));
    return `<section class="dt-meal ${all ? 'ok' : ''}"><div class="dt-mh"><span class="dt-me">${DMEAL[m.meal][1]}</span><span class="grow"><b>${esc(m.label || DMEAL[m.meal][0])}</b>${kc ? `<small class="muted"> · ${kc} kcal</small>` : ''}</span>${ro ? '' : all ? `<span class="pill c" style="--c:var(--green)">${ico('check', 'sm')}Fatto</span>` : `<button class="btn sm primary" data-dte="${di}.${mi}">${ico('check', 'sm')}Mangiato</button>`}</div>
      <div class="dt-items">${m.items.map((it, ii) => { const ok = done && done.has(Diet.key(di, mi, ii)); return `<${ro ? 'div' : 'button'} class="dt-it ${ok ? 'ok' : ''}" ${ro ? '' : `data-dti="${di}.${mi}.${ii}"`}>${ro ? '' : `<span class="check ${ok ? 'on' : ''}"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg></span>`}<span class="grow"><span class="t">${esc(it.n)}</span>${it.alt && it.alt.length ? `<small class="muted" style="display:block">oppure ${esc(it.alt.join(' · '))}</small>` : ''}</span><span class="dt-q tnum">${esc(it.q || (it.g ? it.g + ' g' : ''))}</span></${ro ? 'div' : 'button'}>`; }).join('')}</div></section>`; }).join(''); }
function dietOpen() { const D = Diet.D(); if (!D) return dietImport(); let di = Diet.dayIdx();
  const sh = openSheet({ title: `🥗 ${D.name}`, wide: true, left: { label: 'Chiudi' }, right: { label: 'Spesa', primary: false, act: () => dietShop() }, body: '<div id="dtB" style="display:flex;flex-direction:column;gap:12px"></div>' });
  const paint = () => { const B = $('#dtB', sh.el), today = Diet.dayIdx(), isT = di === today, done = isT ? Diet.done() : new Set(), d = D.days[di], kd = Diet.kcalDay(d);
    B.innerHTML = `${D.days.length > 1 ? `<div class="chips">${D.days.map((x, i) => `<button class="chip" data-dtd="${i}" aria-pressed="${i === di}">${esc(x.label)}${i === today ? ' · oggi' : ''}</button>`).join('')}</div>` : ''}
      <div class="dt-sum"><div><span class="muted">${isT ? 'Oggi' : esc(d.label)}</span><b class="tnum">${kd || D.kcal || '—'} kcal</b></div>${isT ? `<div><span class="muted">Pasti fatti</span><b>${d.meals.filter((m, mi) => m.items.every((_, ii) => done.has(Diet.key(di, mi, ii)))).length}/${d.meals.length}</b></div>` : ''}<div><span class="muted">Obiettivo in Salute</span><b class="tnum">${S.health.prof && S.health.prof.kcal ? S.health.prof.kcal + ' kcal' : 'automatico'}</b></div></div>
      ${isT ? '' : '<p class="muted" style="margin:0;font-size:13.5px">Stai guardando un altro giorno della dieta: per registrare i pasti torna a quello di oggi.</p>'}
      ${dietDayHtml(D, di, done, !isT)}
      ${D.notes.length ? `<details class="dt-det"><summary>Indicazioni del nutrizionista</summary><ul class="dt-notes">${D.notes.map(n => `<li>${esc(n)}</li>`).join('')}</ul></details>` : ''}
      <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" id="dtK">${ico('heart', 'sm')}${D.kcal ? `Obiettivo ${D.kcal} kcal` : 'Obiettivo dalla dieta'}</button><button class="btn" id="dtR">${ico('upload', 'sm')}Nuova dieta</button><button class="btn plain danger" id="dtX">${ico('trash', 'sm')}Togli la dieta</button></div>`;
    $$('[data-dtd]', B).forEach(b => b.onclick = () => { di = +b.dataset.dtd; paint(); });
    $$('[data-dte]', B).forEach(b => b.onclick = () => { const [a, m] = b.dataset.dte.split('.').map(Number), r = Diet.eat(a, m); Sound.done(); Island.toast({ icon: 'heart', c: 'var(--green)', t: `${DMEAL[D.days[a].meals[m].meal][0]} registrato`, s: r.kcal ? `${r.n} alimenti · ${r.kcal} kcal nel diario` : 'Segnato come fatto', ms: 2200 }); paint(); App.refresh(); });
    $$('[data-dti]', B).forEach(b => b.onclick = () => { const [a, m, i] = b.dataset.dti.split('.').map(Number), key = Diet.key(a, m, i), done2 = Diet.done(); if (done2.has(key)) return; Diet.eat(a, m, i); paint(); App.refresh(); });
    $('#dtK', B).onclick = () => { const k = D.kcal || Diet.kcalDay(D.days[Diet.dayIdx()]) || null; if (!k) return; S.health.prof = { ...(S.health.prof || {}), kcal: k }; save('health'); paint(); App.refresh(); Island.toast({ icon: 'heart', c: 'var(--green)', t: `Obiettivo: ${k} kcal al giorno`, ms: 2000 }); };
    $('#dtR', B).onclick = () => { sh.close(); dietImport(); };
    $('#dtX', B).onclick = () => { const old = S.health.diet; delete S.health.diet; save('health'); sh.close(); App.refresh(); undoToast('Dieta tolta', () => { S.health.diet = old; save('health'); App.refresh(); }); }; };
  paint(); return sh; }
function dietShop() { const L = Diet.shop(); if (!L.length) return;
  const sh = openSheet({ title: '🛒 Spesa per la dieta', wide: true, left: { label: 'Annulla' }, right: { label: 'Aggiungi', act: s => { let n = 0; for (const i of L) if (i.on) { Shop.add(i.name, i.qty, 'Dieta'); n++; } s.close(); Island.toast({ icon: 'list', c: 'var(--green)', t: `${n} alimenti nella lista`, action: { label: 'Apri', fn: () => go('shop') }, ms: 3000 }); } },
    body: `<p class="muted" style="margin:0;font-size:14px">Quantità per i prossimi 7 giorni della dieta. Ho tolto quello che hai già in dispensa e le cose di base: toccale per rimetterle.</p><div class="list" id="dsL"></div>` });
  const paint = () => { $('#dsL', sh.el).innerHTML = L.map((i, j) => `<button class="row" data-dsi="${j}"><span class="check ${i.on ? 'on' : ''}"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg></span><span class="grow"><div class="t">${esc(cap(i.name))}${i.qty ? ` <span class="muted">· ${esc(i.qty)}</span>` : ''}</div><div class="s">${i.have ? '🥫 ce l\'hai in dispensa · ' : i.basic ? 'di base · ' : ''}${esc(i.from.join(', '))}</div></span></button>`).join(''); $$('[data-dsi]', sh.el).forEach(b => b.onclick = () => { L[+b.dataset.dsi].on = !L[+b.dataset.dsi].on; paint(); }); };
  paint(); }
ACT.diet = () => dietOpen();
ACT.dietImport = () => dietImport();
ACT.dietEatNow = el => { const [a, m] = String(el.dataset.dtn).split('.').map(Number), D = Diet.D(); if (!D) return; const r = Diet.eat(a, m); Sound.done(); Island.toast({ icon: 'heart', c: 'var(--green)', t: `${DMEAL[D.days[a].meals[m].meal][0]} registrato`, s: r.kcal ? `${r.kcal} kcal nel diario di Salute` : 'Segnato come fatto', ms: 2200 }); App.refresh(); };
{ const oA = VIEWS.health.actions; VIEWS.health.actions = () => `<button class="btn sm" data-act="diet" title="La mia dieta">🥗<span class="hide-narrow">Dieta</span></button>` + oA(); }
TODAY_CARDS.diet = 'Dieta: cosa mangiare adesso'; if (!TODAY_DEFAULT.includes('diet')) TODAY_DEFAULT.splice(3, 0, 'diet');
TODAY_EXTRA.diet = () => { const D = Diet.D(); if (!D) return ''; const m = Diet.nowMeal(); if (!m) return ''; const di = Diet.dayIdx(), d = D.days[di], mi = d.meals.indexOf(m), done = Diet.done(), all = m.items.every((_, ii) => done.has(Diet.key(di, mi, ii)));
  const next = all ? d.meals.slice(mi + 1).find((x, j) => !x.items.every((_, ii) => done.has(Diet.key(di, mi + 1 + j, ii)))) : null, show = next || m, si = d.meals.indexOf(show), sAll = show.items.every((_, ii) => done.has(Diet.key(di, si, ii)));
  return `<section class="card span-6 dt-card"><div class="card-h"><h3>${DMEAL[show.meal][1]} ${next ? 'Prossimo: ' : ''}${esc(show.label || DMEAL[show.meal][0])}</h3><button class="more" data-act="diet">Dieta${ico('right', 'sm')}</button></div>
    <div class="dt-items">${show.items.slice(0, 6).map(it => `<div class="dt-it"><span class="grow t">${esc(it.n)}</span><span class="dt-q tnum">${esc(it.q || (it.g ? it.g + ' g' : ''))}</span></div>`).join('')}${show.items.length > 6 ? `<small class="muted">e altri ${show.items.length - 6}</small>` : ''}</div>
    ${sAll ? `<p class="muted" style="margin:8px 0 0;font-size:14px">✓ Fatto. Brava/o, alla prossima!</p>` : `<button class="btn primary sm" style="margin-top:10px" data-act="dietEatNow" data-dtn="${di}.${si}">${ico('check', 'sm')}Mangiato</button>`}</section>`; };
CMD_ACT.push(['La mia dieta', 'heart', () => ACT.diet()], ['Importa una dieta da foto o file', 'image', () => ACT.dietImport()]);
/* the assistant knows the diet too */
Promise.resolve().then(() => { if (typeof Assistant === 'undefined' || !Assistant.context) return; const oC = Assistant.context.bind(Assistant); Assistant.context = function (...a) { let c = oC(...a); try { const D = Diet.D(), d = Diet.day(); if (D && d) c += `\n\nDIETA (${D.name}${D.kcal ? ', ' + D.kcal + ' kcal/giorno' : ''}), oggi ${d.label}: ${d.meals.map(m => `${m.label || DMEAL[m.meal][0]}: ${m.items.map(i => `${i.n} ${i.q || (i.g ? i.g + ' g' : '')}`).join(', ')}`).join(' | ')}`; } catch (_) {} return c; }; });

