const DISHES = DISH_RAW.split('\n').map((l, i) => { const [n, e, cat, min, ing, v] = l.split('|'); return { id: 'cat' + i, title: n, emoji: e, cat, time: +min, veg: v === 'v', ingredients: String(ing || '').split(';').filter(Boolean).map(x => { const m = x.trim().match(/^(.*?)\s+(\d+(?:[.,]\d+)?(?:\s*[a-zà-ù]+)?|q\.b\.)$/i); return m ? { name: m[1], qty: m[2], g: /g$/.test(m[2]) && !/kg/.test(m[2]) ? parseFloat(m[2]) : /kg$/.test(m[2]) ? parseFloat(m[2]) * 1000 : 0 } : { name: x.trim(), qty: '' }; }) }; });
const DCATS = ['Primi', 'Secondi', 'Piatti unici', 'Zuppe', 'Insalate e leggeri', 'Contorni', 'Pizza e lievitati', 'Colazione', 'Dolci'];
const RTAG_OF = { Primi: 'Primi', Secondi: 'Secondi', 'Piatti unici': 'Piatti unici', Zuppe: 'Primi', 'Insalate e leggeri': 'Leggero', Contorni: 'Contorni', 'Pizza e lievitati': 'Piatti unici', Colazione: 'Colazione', Dolci: 'Dolci' };
const Dish = {
  /** a catalog dish becomes a normal recipe in the Ricettario (once) */
  adopt(d) { let r = S.recipes.find(x => x.cat === d.id || x.title.toLowerCase() === d.title.toLowerCase()); if (r) return r; r = { id: uid(), cat: d.id, title: d.title, emoji: d.emoji, servings: 2, time: d.time, tags: [RTAG_OF[d.cat] || d.cat, ...(d.veg ? ['Vegetariano'] : []), ...(d.time <= 20 ? ['Veloce'] : [])].filter((x, i, a) => a.indexOf(x) === i), ingredients: d.ingredients.map(i => ({ ...i })), steps: [], created: Date.now() }; S.recipes.push(r); save('recipes'); return r; },
  match(q, cat) { q = (q || '').toLowerCase(); return DISHES.filter(d => (!cat || d.cat === cat || (cat === 'Veg' && d.veg) || (cat === 'Veloci' && d.time <= 20)) && (!q || (d.title + ' ' + d.ingredients.map(i => i.name).join(' ')).toLowerCase().includes(q))); },
};
/* the recipe steps are written by the AI the first time you cook a catalog dish */
{ const oC = cookMode; cookMode = function (r, k) { if (r && (!r.steps || !r.steps.length)) { (async () => { const sample = await Cap.get('sample'); if (!sample) return oC(r, k); Island.toast({ icon: 'chef', c: 'var(--orange)', t: 'Scrivo i passaggi…', s: r.title, ms: 2500 });
      try { const out = await sample.json(`Ricetta italiana: "${r.title}" per ${r.servings || 2} persone. Ingredienti: ${(r.ingredients || []).map(i => `${i.name} ${i.qty || ''}`).join(', ')}. Scrivi i passaggi per prepararla, chiari e brevi, con i tempi (es. "cuoci 10 minuti"). Rispondi solo con un array JSON di stringhe, da 4 a 10 passaggi.`); if (Array.isArray(out) && out.length) { r.steps = out.map(String).slice(0, 14); save('recipes'); } } catch (_) {} oC(r, k); })(); return; } return oC(r, k); }; }

/* menu: pick from the Ricettario or from ~200 ideas */
menuPick = function (k, m, after) { const cur = Menu.get(k, m); let q = '', tab = S.recipes.length ? 'mine' : 'idee', cat = '';
  const sh = openSheet({ title: `${cap(parseD(k).toLocaleDateString('it-IT', { weekday: 'long', day: 'numeric' }))} · ${MSLOT.find(x => x[0] === m)[1]}`, wide: true, left: { label: 'Annulla' }, right: { label: 'Fatto', act: s => { const t = $('#mpT', s.el).value.trim(); if (t) Menu.set(k, m, { t }); s.close(); after && after(); } },
    body: `<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">${seg('mpt', [['mine', `Il mio ricettario · ${S.recipes.length}`], ['idee', `Idee · ${DISHES.length}`]], tab)}</div><input class="input" id="mpQ" placeholder="Cerca un piatto o un ingrediente (es. zucchine)"><div class="chips hs" id="mpC"></div><div class="list" id="mpL" style="max-height:46vh;overflow:auto"></div><div class="field"><label for="mpT">Oppure scrivilo a mano</label><input class="input" id="mpT" placeholder="Es. pizza fuori, avanzi" value="${cur && cur.t ? esc(cur.t) : ''}"></div>${cur ? `<button class="btn plain danger" id="mpX" style="align-self:flex-start">${ico('x', 'sm')}Togli</button>` : ''}` });
  const el = sh.el, done = id => { Menu.set(k, m, { r: id }); sh.close(); after && after(); };
  const paint = () => { $('#mpC', el).innerHTML = tab === 'idee' ? ['', 'Veloci', 'Veg', ...DCATS].map(c => `<button class="chip" data-mpc="${c}" aria-pressed="${c === cat}">${c === '' ? 'Tutti' : c === 'Veg' ? 'Vegetariani' : c === 'Veloci' ? 'Veloci (≤ 20 min)' : c}</button>`).join('') : '';
    $$('[data-mpc]', el).forEach(b => b.onclick = () => { cat = b.dataset.mpc; paint(); });
    const L = $('#mpL', el);
    if (tab === 'mine') { const R = S.recipes.filter(r => !q || (r.title + ' ' + (r.ingredients || []).map(i => i.name).join(' ')).toLowerCase().includes(q)).sort((a, b) => (b.fav ? 1 : 0) - (a.fav ? 1 : 0) || a.title.localeCompare(b.title));
      L.innerHTML = R.length ? R.map(r => `<button class="row" data-mpr="${r.id}"><span style="font-size:22px">${r.emoji || '🍽️'}</span><span class="grow"><div class="t">${esc(r.title)}</div><div class="s">${[+r.time ? r.time + ' min' : '', (r.tags || []).slice(0, 2).join(' · ')].filter(Boolean).join(' · ')}</div></span>${cur && cur.r === r.id ? ico('check', 'sm') : ''}</button>`).join('') : `<div class="row muted">${S.recipes.length ? 'Nessuna ricetta trovata' : 'Il ricettario è vuoto: guarda tra le idee'}</div>`;
      $$('[data-mpr]', L).forEach(b => b.onclick = () => done(b.dataset.mpr)); return; }
    const D = Dish.match(q, cat); L.innerHTML = D.length ? D.slice(0, 120).map(d => `<button class="row" data-mpd="${d.id}"><span style="font-size:22px">${d.emoji}</span><span class="grow"><div class="t">${esc(d.title)}</div><div class="s">${d.cat} · ${d.time} min${d.veg ? ' · 🌱' : ''}</div></span></button>`).join('') + (D.length > 120 ? `<div class="row muted">…e altri ${D.length - 120}: affina la ricerca</div>` : '') : '<div class="row muted">Nessun piatto trovato</div>';
    $$('[data-mpd]', L).forEach(b => b.onclick = () => done(Dish.adopt(DISHES.find(d => d.id === b.dataset.mpd)).id)); };
  wireSeg(el, 'mpt', v => { tab = v; paint(); }); $('#mpQ', el).oninput = e => { q = e.target.value.toLowerCase(); paint(); };
  const x = $('#mpX', el); if (x) x.onclick = () => { Menu.set(k, m, null); sh.close(); after && after(); }; paint(); return sh; };
/* auto-fill: your recipes first, then varied ideas (lighter lunches on weekdays, a main course in the evening) */
{ const oAuto = Menu.auto.bind(Menu); Menu.auto = function (days, onlyEmpty = true) { if (S.recipes.length >= 10) return oAuto(days, onlyEmpty); let n = 0; const used = new Set(Object.values(S.menu).flatMap(d => Object.values(d).map(s => s.r)).filter(Boolean));
  const pick = (cats, wk) => { const mine = S.recipes.filter(r => !used.has(r.id) && (r.tags || []).some(t => cats.includes(t))); if (mine.length && Math.random() < .5) return mine[Math.floor(Math.random() * mine.length)]; const P = DISHES.filter(d => cats.includes(d.cat) && (!wk || d.time <= 35) && !used.has((S.recipes.find(r => r.cat === d.id) || {}).id)); const d = P[Math.floor(Math.random() * P.length)] || DISHES[Math.floor(Math.random() * DISHES.length)]; return Dish.adopt(d); };
  for (const k of days) for (const [m] of MSLOT) { if (onlyEmpty && this.get(k, m)) continue; const wk = dowIdx(k) < 5, r = m === 'pranzo' ? pick(wk ? ['Primi', 'Insalate e leggeri', 'Piatti unici'] : ['Primi', 'Piatti unici', 'Pizza e lievitati'], wk) : pick(['Secondi', 'Zuppe', 'Piatti unici', ...(dowIdx(k) >= 4 ? ['Pizza e lievitati'] : [])], wk); used.add(r.id); S.menu[k] ||= {}; S.menu[k][m] = { r: r.id }; n++; }
  save('menu'); return n; }; }
/* browse the ideas from the Ricettario */
ACT.dishBrowse = () => { let q = '', cat = '';
  const sh = openSheet({ title: `Idee · ${DISHES.length} piatti`, wide: true, left: { label: 'Chiudi' }, body: `<input class="input" id="dbQ" placeholder="Cerca un piatto o un ingrediente"><div class="chips hs" id="dbC"></div><div class="list" id="dbL" style="max-height:56vh;overflow:auto"></div>` });
  const el = sh.el, paint = () => { $('#dbC', el).innerHTML = ['', 'Veloci', 'Veg', ...DCATS].map(c => `<button class="chip" data-dbc="${c}" aria-pressed="${c === cat}">${c === '' ? 'Tutti' : c === 'Veg' ? 'Vegetariani' : c === 'Veloci' ? 'Veloci' : c}</button>`).join(''); $$('[data-dbc]', el).forEach(b => b.onclick = () => { cat = b.dataset.dbc; paint(); });
    const D = Dish.match(q, cat); $('#dbL', el).innerHTML = D.map(d => { const has = S.recipes.some(r => r.cat === d.id); return `<div class="row"><span style="font-size:22px">${d.emoji}</span><span class="grow"><div class="t">${esc(d.title)}</div><div class="s">${d.cat} · ${d.time} min${d.veg ? ' · 🌱' : ''} · ${esc(d.ingredients.slice(0, 4).map(i => i.name.toLowerCase()).join(', '))}</div></span>${has ? '<span class="pill c" style="--c:var(--green)">nel ricettario</span>' : `<button class="btn sm" data-dba="${d.id}">${ico('plus', 'sm')}Aggiungi</button>`}</div>`; }).join('') || '<div class="row muted">Nessun piatto trovato</div>';
    $$('[data-dba]', el).forEach(b => b.onclick = () => { Dish.adopt(DISHES.find(d => d.id === b.dataset.dba)); paint(); App.refresh(); Island.toast({ icon: 'chef', c: 'var(--orange)', t: 'Aggiunto al ricettario', s: 'I passaggi li scrivo quando lo cucini', ms: 1800 }); }); };
  $('#dbQ', el).oninput = e => { q = e.target.value.toLowerCase(); paint(); }; paint(); return sh; };
{ const oA = VIEWS.recipes.actions; VIEWS.recipes.actions = () => `<button class="btn sm" data-act="dishBrowse">💡<span class="hide-narrow">Idee</span></button>` + oA(); }

/* ---------- ricerca più ampia: film, serie, libri, podcast e GIOCHI ---------- */
const WIKI = async (lang, q, tpl, n = 20) => { const j = await Media.get(`https://${lang}.wikipedia.org/w/api.php?` + new URLSearchParams({ action: 'query', format: 'json', origin: '*', generator: 'search', gsrsearch: `${q}${tpl ? ' hastemplate:"' + tpl + '"' : ''}`, gsrlimit: n, prop: 'pageimages|extracts|description', piprop: 'thumbnail', pithumbsize: 500, exintro: 1, explaintext: 1, exsentences: 3, exlimit: n })); return Object.values((j.query || {}).pages || {}).sort((a, b) => (a.index || 0) - (b.index || 0)); };
const yearOf = s => { const m = String(s || '').match(/\b(19[2-9]\d|20[0-4]\d)\b/); return m ? m[1] : ''; };
{ const oS = Media.search.bind(Media);
  Media.search = async function (type, q) { q = String(q || '').trim(); if (!q) return []; const seen = new Set(), out = [], push = r => { const k = r.title.toLowerCase().replace(/[^a-z0-9à-ù]/g, ''); if (!r.title || seen.has(k)) return; seen.add(k); out.push(r); };
    if (type === 'game') {
      const [w1, w2, ap] = await Promise.all([WIKI('it', q, 'Videogioco').catch(() => []), WIKI('en', q, 'Infobox video game').catch(() => []), this.get('https://itunes.apple.com/search?' + new URLSearchParams({ term: q, country: 'it', media: 'software', entity: 'software', limit: 25 })).catch(() => ({}))]);
      for (const p of [...w1, ...w2]) push({ title: p.title.replace(/ \((videogioco|video game)[^)]*\)$/i, ''), creator: '', year: yearOf(p.description) || yearOf(p.extract), cover: p.thumbnail ? p.thumbnail.source : '', genre: p.description || 'Videogioco', plot: p.extract || '' });
      for (const d of (ap.results || []).filter(d => (d.genres || []).includes('Games') || d.primaryGenreName === 'Games')) push({ title: d.trackName, creator: d.artistName || '', year: (d.releaseDate || '').slice(0, 4), cover: this.big(d.artworkUrl512 || d.artworkUrl100), genre: 'App · ' + ((d.genres || [])[1] || 'Gioco'), plot: (d.description || '').slice(0, 600), url: d.trackViewUrl });
      return out.slice(0, 30); }
    if (type === 'book') { const r = await oS(type, q).catch(() => []); r.forEach(push);
      try { const j = await this.get('https://openlibrary.org/search.json?' + new URLSearchParams({ q, limit: 30, offset: 10, fields: 'key,title,author_name,first_publish_year,cover_i,number_of_pages_median' })); for (const d of j.docs || []) push({ title: d.title, creator: (d.author_name || [])[0] || '', year: String(d.first_publish_year || ''), cover: d.cover_i ? `https://covers.openlibrary.org/b/id/${d.cover_i}-L.jpg` : '', pages: d.number_of_pages_median || null }); } catch (_) {}
      return out.slice(0, 30); }
    const p = { movie: { media: 'movie', entity: 'movie' }, tv: { media: 'tvShow', entity: 'tvSeason' }, podcast: { media: 'podcast', entity: 'podcast' } }[type];
    if (!p) return oS(type, q);
    const [j, w] = await Promise.all([this.get('https://itunes.apple.com/search?' + new URLSearchParams({ term: q, country: 'it', lang: 'it_it', limit: 60, ...p })).catch(() => ({})), type === 'podcast' ? [] : WIKI('it', q, type === 'movie' ? 'Film' : 'Fiction TV').catch(() => [])]);
    for (const d of j.results || []) { const title = type === 'tv' ? String(d.artistName || d.collectionName || '').replace(/,? (Stagione|Season) \d+.*$/i, '') : (d.trackName || d.collectionName); if (!title) continue; push({ title, creator: type === 'tv' ? '' : d.artistName || '', year: (d.releaseDate || '').slice(0, 4), cover: this.big(d.artworkUrl100 || d.artworkUrl600), genre: d.primaryGenreName || '', plot: d.longDescription || d.shortDescription || '', url: d.collectionViewUrl || d.trackViewUrl || '' }); }
    for (const pg of w) push({ title: pg.title.replace(/ \((film|serie televisiva|miniserie)[^)]*\)$/i, ''), creator: '', year: yearOf(pg.description) || yearOf(pg.extract), cover: pg.thumbnail ? pg.thumbnail.source : '', genre: pg.description || '', plot: pg.extract || '' });
    return out.slice(0, 30); }; }

