ACT.mediaBrowse = () => { let tp = UI.mType && MEDIA_CAT[UI.mType] ? UI.mType : 'movie', g = '', q = '';
  const sh = openSheet({ title: 'Sfoglia', wide: true, left: { label: 'Chiudi' }, right: { label: 'Sorprendimi', primary: false, act: () => { const L = list().filter(x => !has(x)); if (!L.length) return; const x = L[Math.floor(Math.random() * L.length)]; q = x.title.toLowerCase(); $('#mbQ', sh.el).value = x.title; paint(); } },
    body: `${seg('mbt', Object.keys(MEDIA_CAT).map(k => [k, MTYPE[k][1] + ' ' + MTYPE[k][0]]), tp)}<input class="input" id="mbQ" placeholder="Filtra per titolo, autore o regista"><div class="chips hs" id="mbG"></div><div class="list" id="mbL" style="max-height:52vh;overflow:auto"></div>` });
  const el = sh.el, has = x => S.media.some(m => m.type === tp && m.title.toLowerCase() === x.title.toLowerCase()), list = () => MEDIA_CAT[tp].filter(x => (!g || x.genre === g) && (!q || (x.title + ' ' + x.creator).toLowerCase().includes(q)));
  const paint = () => { const G = [...new Set(MEDIA_CAT[tp].map(x => x.genre))].sort(); $('#mbG', el).innerHTML = ['', ...G].map(x => `<button class="chip" data-mbg="${esc(x)}" aria-pressed="${x === g}">${x || 'Tutti'}</button>`).join(''); $$('[data-mbg]', el).forEach(b => b.onclick = () => { g = b.dataset.mbg; paint(); });
    const L = list(); $('#mbL', el).innerHTML = `<div class="row muted" style="font-size:13px">${L.length} titoli</div>` + L.map((x, i) => `<div class="row"><span class="md-th md-ph" style="--c:${MTYPE[tp][2]}">${MTYPE[tp][1]}</span><span class="grow" style="min-width:0"><div class="t">${esc(x.title)}</div><div class="s">${[x.year, x.genre, x.creator].filter(Boolean).map(esc).join(' · ')}</div></span>${has(x) ? '<span class="pill c" style="--c:var(--green)">in lista</span>' : `<button class="btn sm" data-mba="${esc(x.title)}">${ico('plus', 'sm')}Aggiungi</button>`}</div>`).join('');
    $$('[data-mba]', el).forEach(b => b.onclick = async () => { const x = MEDIA_CAT[tp].find(z => z.title === b.dataset.mba); const m = { id: uid(), type: tp, status: 'want', rating: 0, added: Date.now(), title: x.title, year: x.year, genre: x.genre, creator: x.creator }; S.media.push(m); save('media'); b.replaceWith(Object.assign(document.createElement('span'), { className: 'pill c', textContent: 'Aggiunto ✓', style: '--c:var(--green)' })); App.refresh();
      try { const R = await Media.search(tp, x.title), r = R.find(z => z.title.toLowerCase() === x.title.toLowerCase() && (!x.year || !z.year || Math.abs(+z.year - +x.year) <= 1)) || R.find(z => z.title.toLowerCase().includes(x.title.toLowerCase().slice(0, 12))); if (r) { for (const k of ['cover', 'plot', 'url', 'pages']) if (r[k] && !m[k]) m[k] = r[k]; save('media'); App.refresh(); } } catch (_) {} }); };
  wireSeg(el, 'mbt', v => { tp = v; g = ''; paint(); }); $('#mbQ', el).oninput = e => { q = e.target.value.toLowerCase(); paint(); }; paint(); return sh; };
