ACT.park = () => parkSheet();
{ const old = Alerts.list.bind(Alerts); Alerts.list = function (hours = 48) { const out = old(hours), now = Date.now(); const P = S.park || {}; if (P.until) { for (const [k, d, t] of [['pk10', 10 * 60e3, '🅿️ Le strisce blu scadono tra 10 minuti'], ['pk0', 0, '🅿️ Strisce blu scadute']]) { const at = P.until - d, key = `${k}:${P.until}`; if (!this.fired[key] && at >= now - 5 * 60e3 && at <= now + hours * 36e5) out.push({ key, at, title: t, body: P.note || 'Torna all\'auto o ricarica il parcheggio', view: 'today' }); } } return out; }; }
TODAY_CARDS.park = 'Parcheggio'; if (!TODAY_DEFAULT.includes('park')) TODAY_DEFAULT.splice(1, 0, 'park');
