CMD_ACT.push(['Nuovo farmaco', 'heart', () => { go('meds'); medEdit(); }], ['Dove l\'ho messo?', 'pin', () => ACT.stashFind()], ['Segna dove ho messo una cosa', 'pin', () => stashEdit()], ['Manutenzione casa', 'clock', () => { UI.homeTab = 'maint'; go('home'); }], ['Dove ho parcheggiato', 'car', () => ACT.park()], ['Salva il parcheggio', 'car', () => ACT.park()]);
