for (const k of ['parties', 'spots']) if (!CORE.includes(k)) CORE.push(k);
S.parties ||= []; S.spots ||= [];

/* ---------- eventi e feste ---------- */
const PKIND = { festa: ['Festa', '🎉'], compleanno: ['Compleanno', '🎂'], cena: ['Cena', '🍝'], grigliata: ['Grigliata', '🍖'], aperitivo: ['Aperitivo', '🍹'], laurea: ['Laurea', '🎓'], viaggio: ['Gita', '🚐'], altro: ['Evento', '📅'] };
const GST = { si: ['Viene', 'var(--green)', '✓'], forse: ['Forse', 'var(--orange)', '?'], no: ['Non viene', 'var(--red)', '✕'], '': ['Da sentire', 'var(--gray)', '…'] };
const Party = {
  count(p) { const G = p.guests || []; return { si: G.filter(g => g.st === 'si').reduce((s, g) => s + 1 + (+g.plus || 0), 0) + 1, forse: G.filter(g => g.st === 'forse').length, no: G.filter(g => g.st === 'no').length, open: G.filter(g => !g.st).length, all: G.length }; },
  spent(p) { return (p.shop || []).reduce((s, x) => s + (+x.price || 0), 0); },
  invite(p) { const K = PKIND[p.kind] || PKIND.altro; return `${K[1]} ${p.title}\n📅 ${cap(parseD(p.date).toLocaleDateString('it-IT', { weekday: 'long', day: 'numeric', month: 'long' }))}${p.time ? ' alle ' + p.time : ''}${p.place ? '\n📍 ' + p.place : ''}${p.notes ? '\n\n' + p.notes : ''}\n\nMi dici se ci sei? 🙂`; },
};
{ const g = NAV.find(x => x.g === 'Vita') || NAV[0]; g.items.push(['parties', 'Eventi e feste', 'star'], ['spots', 'I miei posti', 'pin']); }
