{ const old = Alerts.list.bind(Alerts); Alerts.list = function (hours = 48) { const out = old(hours), now = Date.now(); for (const p of S.parties) { if (p.date < todayK()) continue; const c = Party.count(p), k = addDK(p.date, -3), td = (p.todo || []).filter(x => !x.ok).length; const key = `pt3:${p.id}:${p.date}`; let at = this.at(k, '18:00'); if (at < now && k <= todayK() && p.date > todayK()) at = now + 60e3; if (!this.fired[key] && (c.open || td) && at >= now - 10 * 60e3 && at <= now + hours * 36e5) out.push({ key, at, title: `${(PKIND[p.kind] || PKIND.altro)[1]} ${p.title} tra ${dayDiff(todayK(), p.date)} giorni`, body: [c.open && `${c.open} invitati da sentire`, td && `${td} cose da fare`].filter(Boolean).join(' · '), view: 'parties' }); } return out; }; }
