  mount(root) { wireSeg(root, 'spm', v => { UI.spM = v; App.render(); }); $$('[data-spf]', root).forEach(b => b.onclick = () => { UI.spF = b.dataset.spf; App.render(); }); $$('[data-spo]', root).forEach(b => b.onclick = () => spotEdit(b.dataset.spo));
    const mp = $('#spMap', root); if (mp) { const f = UI.spF || ''; miniMap(mp, S.spots.filter(s => (!f || (f === 'want' ? s.want : s.kind === f))).map(s => ({ lat: s.lat, lng: s.lng, e: (SPK[s.kind] || SPK.altro)[1], t: s.name, s: s.want ? 'da provare' : '★'.repeat(+s.rating || 0), fn: () => spotEdit(s.id) }))); } },
