    if (k === 'exammode' || k === 'vacation') return 100;
    if (k === 'park' && typeof Park !== 'undefined' && Park.on()) return Park.left() != null ? 95 : 40;
    if (k === 'meds' && typeof Med !== 'undefined') { const T = Med.today().filter(x => !x.ok).map(x => hm2m(x.t) - m); if (T.some(d => d < 0)) return 90; if (T.some(d => d <= 60)) return 80; return 0; }
