    if (k === 'menu') return (m >= 660 && m <= 840) || (m >= 1080 && m <= 1260) ? 60 : 0;
    if (k === 'parties' && S.parties) return S.parties.some(p => p.date === t || p.date === addDK(t, 1)) ? 75 : 0;
