/* ---------- presentation ---------- */
ACT.nbPresent = () => { const B = Board, w = $('#boardWrap'); if (!w) return; if (document.fullscreenElement) { document.exitFullscreen(); return; } B.present = true; B.prevTool = B.tool; B.tool = 'laser'; w.classList.add('nb-present'); (w.requestFullscreen ? w.requestFullscreen() : Promise.reject()).catch(() => {}); B.paintPalette(); Island.toast({ icon: 'laser', t: 'Presentazione', s: 'Laser attivo · Esc per uscire', ms: 2200 }); setTimeout(() => B.resize(), 300); };
