  week(a, k = todayK()) { const ws = addDK(k, -((parseD(k).getDay() + 6) % 7)), we = addDK(ws, 6); return this.P().filter(p => p.acct === a.id && (p.st === 'prog' || p.st === 'pub') && p.date >= ws && p.date <= we).length; },
  save() { save('social'); },
  /* ---------- best times: your posts first, general rules as fallback ---------- */
  heat(a) {
    const N = this.net(a), H = Array.from({ length: 7 }, () => Array(24).fill(0)), D = this.P().filter(p => p.acct === a.id && p.st === 'pub' && p.date && p.time && p.perf).concat((a.media || []).map(m => ({ date: m.k, time: m.t, perf: m.perf }))).filter(p => /^\d{4}-\d\d-\d\d$/.test(p.date) && /^\d\d:\d\d/.test(p.time));
    if (D.length >= 6) { const avg = D.reduce((s, p) => s + this.eng(p), 0) / D.length || 1, C = Array.from({ length: 7 }, () => Array(24).fill(0));
      for (const p of D) { const d = parseD(p.date).getDay(), h = +String(p.time).slice(0, 2); for (let dh = -1; dh <= 1; dh++) { const hh = (h + dh + 24) % 24, w = dh ? .5 : 1; H[d][hh] += this.eng(p) / avg * w; C[d][hh] += w; } }
      for (let d = 0; d < 7; d++) for (let h = 0; h < 24; h++) H[d][h] = C[d][h] ? H[d][h] / C[d][h] : 0;
      return { H, own: true, n: D.length }; }
    for (const [d0, d1, h0, h1, w] of N.best) for (let d = d0; d <= d1; d++) for (let h = h0; h < h1; h++) H[d % 7][h] = Math.max(H[d % 7][h], w);
    return { H, own: false, n: D.length };
  },
