{ const base = itemsOn; itemsOn = function (k) { const out = base(k); for (const p of Soc.P()) if (p.st === 'prog' && p.date === k) { const a = Soc.acct(p.acct), N = Soc.net(a); out.push({ kind: 'social', id: p.id, k, title: `${N.e} ${p.title || 'Post'}${a ? ' · ' + a.name : ''}`, cat: 'social', allDay: !p.time, s: p.time || '', e: p.time ? m2hm(hm2m(p.time) + 15) : '' }); } return out.sort((a, b) => (b.allDay - a.allDay) || a.s.localeCompare(b.s)); }; }
document.addEventListener('click', e => { const o = e.target.closest && e.target.closest('[data-open^="social:"]'); if (!o) return; e.stopImmediatePropagation(); e.preventDefault(); postEdit(o.dataset.open.split(':')[1]); }, true);
