/* ---------- post editor ---------- */
function postEdit(id, preset = {}) {
  const p0 = id ? Soc.P().find(p => p.id === id) : null; if (id && !p0) return;
  const A = Soc.A(); if (!A.length) { acctEdit(); return; }
  const f = p0 ? { ...p0, tags: (p0.tags || []).slice() } : { id: uid(), acct: preset.acct || (A[0] && A[0].id), st: preset.st || 'bozza', title: preset.title || '', hook: preset.hook || '', caption: preset.caption || '', tags: preset.tags || [], fmt: preset.fmt || '', date: preset.date || '', time: preset.time || '', notes: '', created: Date.now() };
  const sh = openSheet({ title: p0 ? (p0.title || 'Post') : 'Nuovo post', wide: true, left: { label: p0 ? 'Fine' : 'Annulla', act: s => { if (p0) store(s); s.close(); } }, right: p0 ? null : { label: 'Salva', act: s => { store(s); s.close(); } }, body: '<div id="peB" style="display:flex;flex-direction:column;gap:12px"></div>', onClose: () => { if (p0 && !f._gone && Soc.P().some(p => p.id === f.id)) store(); } });
  const B = $('#peB', sh.el);
  const read = () => { const g = q => $(q, B); if (!g('#peT')) return; f.title = g('#peT').value.trim(); f.caption = g('#peC').value; f.tags = g('#peH').value.split(/[\s,]+/).filter(Boolean).map(t => t.startsWith('#') ? t : '#' + t); f.date = g('#peD').value; f.time = g('#peTi').value; f.notes = g('#peN').value; f.acct = g('#peA').value; f.fmt = g('#peF').value; };
  const store = () => { read(); if (f.st === 'prog' && !f.date) { const s = Soc.nextSlot(Soc.acct(f.acct)); f.date = s.k; f.time = s.t; } const i = Soc.P().findIndex(p => p.id === f.id); if (i >= 0) Soc.P()[i] = f; else Soc.P().push(f); Soc.save(); Alerts.sync && Alerts.sync(); App.refresh(); };
  const full = () => (f.caption || '') + (f.tags.length ? '\n\n' + f.tags.join(' ') : '');
  const paint = () => { const a = Soc.acct(f.acct), N = Soc.net(a), len = full().length, over = len > N.max;
    B.innerHTML = `<div class="form-grid"><div class="field"><label for="peA">Pagina</label><select class="input" id="peA">${A.map(x => `<option value="${x.id}" ${x.id === f.acct ? 'selected' : ''}>${Soc.net(x).e} ${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label for="peF">Formato</label><select class="input" id="peF">${N.fmt.map(x => `<option ${x === f.fmt ? 'selected' : ''}>${x}</option>`).join('')}</select></div></div>
      <div class="field"><span class="lbl">Stato</span>${seg('peS', Object.entries(PST_ST).map(([k, v]) => [k, v[1] + ' ' + v[0]]), f.st)}</div>
      <input class="input" id="peT" placeholder="Di cosa parla (titolo interno)" value="${esc(f.title)}">${f.hook ? `<p class="muted" style="margin:-4px 0 0;font-size:13.5px">🪝 ${esc(f.hook)}</p>` : ''}
      <div class="field"><label for="peC" style="display:flex;justify-content:space-between"><span>Testo</span><span class="tnum" style="color:${over ? 'var(--red)' : 'var(--label-3)'}">${len.toLocaleString('it-IT')} / ${N.max.toLocaleString('it-IT')}</span></label><textarea class="input soc-cap" id="peC" rows="8" placeholder="Didascalia, script o thread…">${esc(f.caption)}</textarea></div>
      <input class="input" id="peH" placeholder="#hashtag (separati da spazio)" value="${esc(f.tags.join(' '))}">
      <div class="soc-ai">${[['cap', '✨ Scrivi / migliora'], ['var', '🎭 3 versioni'], ['script', '🎬 Script video'], ['thread', '🧵 Thread'], ['img', '📷 Dalla foto']].map(([k, l]) => `<button class="chip" data-peai="${k}">${l}</button>`).join('')}<select class="input" id="peTo" style="width:auto;height:34px"><option value="">↪︎ Adatta a…</option>${Object.entries(NETS).filter(([k]) => k !== (a && a.net)).map(([k, n]) => `<option value="${k}">${n.e} ${n.n}</option>`).join('')}</select></div>${f.tip ? `<p class="soc-tip">💡 ${esc(f.tip)}</p>` : ''}<div id="peVar"></div>
      <div class="form-grid"><div class="field"><label for="peD">Giorno</label><input class="input" id="peD" type="date" value="${f.date}"></div><div class="field"><label for="peTi">Ora</label><input class="input" id="peTi" type="time" value="${f.time}"></div></div>
      ${a ? `<button class="btn sm plain" id="peBest" style="align-self:flex-start;margin-top:-6px">⏱️ Al momento migliore (${(s => `${relDay(s.k)} alle ${s.t}`)(Soc.nextSlot(a))})</button>` : ''}
      <textarea class="input" id="peN" rows="2" placeholder="Note (foto da fare, musica, collaborazioni…)">${esc(f.notes || '')}</textarea>
      ${f.st === 'pub' ? `<div class="card" style="background:var(--cell);display:flex;flex-direction:column;gap:8px"><b>Com'è andato?</b><div class="soc-perf">${[['likes', 'Mi piace'], ['comments', 'Commenti'], ['shares', 'Condivisioni'], ['saves', 'Salvataggi'], ['views', 'Visualizzazioni']].map(([k, l]) => `<label><small>${l}</small><input class="input" type="number" min="0" data-pf="${k}" value="${(f.perf || {})[k] ?? ''}"></label>`).join('')}</div></div>` : ''}
      <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" id="peCopy">${ico('copy', 'sm')}Copia e apri ${N.n}</button>${p0 ? `<button class="btn" id="peDup">${ico('copy', 'sm')}Duplica</button><button class="btn danger" id="peDel">${ico('trash', 'sm')}Elimina</button>` : ''}</div>`;
    wireSeg(B, 'peS', v => { read(); f.st = v; if (v === 'prog' && !f.date) { const s = Soc.nextSlot(Soc.acct(f.acct)); f.date = s.k; f.time = s.t; } paint(); });
    $('#peA', B).onchange = () => { read(); paint(); }; $('#peC', B).oninput = () => { const L = $('#peC', B).value.length + (f.tags.length ? 2 + f.tags.join(' ').length : 0), lab = $('label[for=peC] .tnum', B); if (lab) { lab.textContent = `${L.toLocaleString('it-IT')} / ${N.max.toLocaleString('it-IT')}`; lab.style.color = L > N.max ? 'var(--red)' : 'var(--label-3)'; } };
    const best = $('#peBest', B); if (best) best.onclick = () => { read(); const s = Soc.nextSlot(a); f.date = s.k; f.time = s.t; if (f.st !== 'pub') f.st = 'prog'; paint(); };
    $$('[data-pf]', B).forEach(i => i.onchange = () => { f.perf ||= {}; f.perf[i.dataset.pf] = +i.value || 0; });
    $('#peCopy', B).onclick = async () => { read(); try { await navigator.clipboard.writeText(full()); } catch (_) {} Island.toast({ icon: 'copy', c: 'var(--green)', t: 'Testo copiato', s: 'Incollalo nell\'app e pubblica', ms: 2400 }); if (f.st !== 'pub') { f.st = 'pub'; f.date ||= todayK(); f.time ||= m2hm(new Date().getHours() * 60 + new Date().getMinutes()); store(); } window.open(N.app, '_blank', 'noopener'); paint(); };
    const dup = $('#peDup', B); if (dup) dup.onclick = () => { read(); sh.close(); postEdit(null, { ...f, st: 'bozza', date: '', time: '' }); };
    const del = $('#peDel', B); if (del) del.onclick = () => { f._gone = 1; S.social.posts = Soc.P().filter(p => p.id !== f.id); Soc.save(); sh.close(); App.refresh(); Island.toast({ icon: 'trash', c: 'var(--gray)', t: 'Post eliminato', ms: 1600 }); };
    $('#peTo', B).onchange = async e => { const to = e.target.value; if (!to) return; read(); if (!f.caption.trim()) { Island.toast({ icon: 'spark', c: 'var(--orange)', t: 'Scrivi prima il testo', ms: 2000 }); return; } const r = await Soc.adapt(a, f, to); if (!r || !r.caption) return; const dest = Soc.A().find(x => x.net === to); postEdit(null, { acct: dest ? dest.id : f.acct, st: 'bozza', title: f.title, caption: r.caption, tags: r.hashtags || [], fmt: NETS[to].fmt[0] }); };
    $$('[data-peai]', B).forEach(b => b.onclick = async () => { read(); const k = b.dataset.peai; b.disabled = true;
      try {
        if (k === 'var') { if (!f.caption.trim()) { Island.toast({ icon: 'spark', c: 'var(--orange)', t: 'Scrivi prima il testo (o usa “Scrivi”)', ms: 2200 }); return; } const r = await Soc.variants(a, f); const V = (r && r.v) || []; $('#peVar', B).innerHTML = V.length ? `<div class="soc-vars">${V.map((v, i) => `<button class="soc-var" data-vv="${i}"><b>${esc(v.tone)}</b><span>${esc(v.caption)}</span></button>`).join('')}</div>` : ''; $$('[data-vv]', B).forEach(x => x.onclick = () => { f.caption = V[+x.dataset.vv].caption; paint(); }); return; }
        if (k === 'img') { const inp = document.createElement('input'); inp.type = 'file'; inp.accept = 'image/*'; inp.onchange = async () => { const file = inp.files[0]; if (!file) return; const r = await Soc.ai(`Sei un copywriter per i social. ${Soc.brief(a)}\nScrivi la didascalia per questa foto per ${N.n}: hook nella prima riga, testo breve, invito all'azione. Poi ${N.tags[1] ? N.tags[1] + ' hashtag' : 'nessun hashtag'}. Rispondi solo con JSON {"title":"di cosa parla in 5 parole","caption":"","hashtags":[],"tip":""}.`, { images: [file], msg: 'Guardo la foto…' }); if (r && r.caption) { f.caption = r.caption; f.tags = r.hashtags || f.tags; f.title ||= r.title || ''; f.tip = r.tip || ''; paint(); } }; inp.click(); return; }
        const r = await Soc.write(a, f, k === 'script' ? 'script' : k === 'thread' ? 'thread' : 'caption'); if (r && r.caption) { f.caption = r.caption; if (r.hashtags && r.hashtags.length) f.tags = r.hashtags.map(t => t.startsWith('#') ? t : '#' + t); f.tip = r.tip || ''; if (k === 'script') f.fmt = N.fmt.find(x => /video|reel|short/.test(x)) || f.fmt; paint(); }
      } finally { b.disabled = false; } });
  };
  paint();
}

/* ---------- account editor ---------- */
function acctEdit(id) {
  const a0 = id ? Soc.acct(id) : null, f = a0 ? { ...a0 } : { id: uid(), net: 'instagram', name: '', handle: '', topic: '', audience: '', tone: '', goalTxt: '', per: 3, stats: [] };
  openSheet({ title: a0 ? a0.name : 'Nuova pagina', wide: true, left: { label: 'Annulla' }, right: { label: a0 ? 'Fine' : 'Aggiungi', act: s => { const g = q => $(q, s.el).value.trim(); f.name = g('#saN') || NETS[f.net].n; f.handle = g('#saH'); f.topic = g('#saT'); f.audience = g('#saP'); f.tone = g('#saV'); f.goalTxt = g('#saG'); f.per = clamp(+g('#saW') || 3, 1, 21); const fl = +g('#saF'); if (fl >= 0 && g('#saF') !== '') Soc.stat(f, fl);
      const i = Soc.A().findIndex(x => x.id === f.id); if (i >= 0) Soc.A()[i] = f; else Soc.A().push(f); Soc.save(); s.close(); App.refresh(); } },
    body: `<div class="field"><span class="lbl">Social</span><div class="chips">${Object.entries(NETS).map(([k, n]) => `<button type="button" class="chip" data-sn="${k}" aria-pressed="${k === f.net}">${n.e} ${n.n}</button>`).join('')}</div></div>
      <div class="form-grid"><div class="field"><label for="saN">Nome della pagina</label><input class="input" id="saN" value="${esc(f.name)}" placeholder="Es. La mia pagina"></div><div class="field"><label for="saH">Nome utente</label><input class="input" id="saH" value="${esc(f.handle || '')}" placeholder="@nome"></div></div>
      <div class="field"><label for="saT">Di cosa parla</label><input class="input" id="saT" value="${esc(f.topic || '')}" placeholder="Es. ricette veloci per studenti, fotografia di viaggio…"></div>
      <div class="field"><label for="saP">A chi parla</label><input class="input" id="saP" value="${esc(f.audience || '')}" placeholder="Es. studenti 19-26 anni, appassionati di…"></div>
      <div class="form-grid"><div class="field"><label for="saV">Tono di voce</label><input class="input" id="saV" value="${esc(f.tone || '')}" placeholder="Es. ironico, diretto, tecnico"></div><div class="field"><label for="saG">Obiettivo</label><input class="input" id="saG" value="${esc(f.goalTxt || '')}" placeholder="Es. 1.000 follower entro giugno"></div></div>
      <div class="form-grid"><div class="field"><label for="saW">Post a settimana</label><input class="input" id="saW" type="number" min="1" max="21" value="${f.per || 3}"></div><div class="field"><label for="saF">Follower oggi</label><input class="input" id="saF" type="number" min="0" value="${Soc.followers(f) ?? ''}" ${f.meta ? 'disabled title="Arriva da Meta"' : ''}></div></div>
      <p class="muted" style="margin:0;font-size:13px">Più descrivi la pagina, più le idee e i testi dell'IA saranno su misura.</p>
      ${a0 ? `<button class="btn danger" id="saDel" style="align-self:flex-start">${ico('trash', 'sm')}Togli la pagina</button>` : ''}`,
    onMount(el) { $$('[data-sn]', el).forEach(b => b.onclick = () => { f.net = b.dataset.sn; $$('[data-sn]', el).forEach(x => x.setAttribute('aria-pressed', String(x === b))); }); const d = $('#saDel', el); if (d) d.onclick = () => { S.social.accts = Soc.A().filter(x => x.id !== f.id); S.social.posts = Soc.P().filter(p => p.acct !== f.id); Soc.save(); Sheets.slice().forEach(s => s.close()); App.refresh(); }; } });
}

/* ---------- connect Meta (Instagram professional + Facebook pages) ---------- */
function metaConnect() {
  openSheet({ title: 'Collega Instagram e Facebook', wide: true, left: { label: 'Annulla' }, right: { label: 'Collega', act: async s => { const tok = $('#mtT', s.el).value.trim(), msg = $('#mtMsg', s.el); if (!tok) return; msg.style.color = ''; msg.textContent = 'Controllo…';
      try { await AIK.set('meta', tok); const L = await Soc.metaPages(); if (!L.length) throw new Error('Nessuna pagina trovata: il token deve avere i permessi indicati sopra');
        let n = 0; for (const pg of L) { if (pg.instagram_business_account) { const ig = pg.instagram_business_account, ex = Soc.A().find(a => a.meta && a.meta.ig === ig.id); const a = ex || { id: uid(), net: 'instagram', name: ig.username, handle: '@' + ig.username, per: 3, stats: [] }; a.meta = { ig: ig.id, page: pg.id }; Soc.stat(a, ig.followers_count || 0); if (!ex) Soc.A().push(a); n++; }
          const exF = Soc.A().find(a => a.meta && a.meta.page === pg.id && a.net === 'facebook'); const fb = exF || { id: uid(), net: 'facebook', name: pg.name, per: 3, stats: [] }; fb.meta = { page: pg.id }; Soc.stat(fb, pg.followers_count || pg.fan_count || 0); if (!exF) Soc.A().push(fb); n++; }
        Soc.save(); s.close(); Island.toast({ icon: 'share', c: 'var(--green)', t: 'Meta collegato', s: `${n} ${n === 1 ? 'pagina' : 'pagine'} · aggiorno i post…`, ms: 2600 }); await Soc.sync(true); App.refresh();
      } catch (e) { await AIK.set('meta', ''); msg.style.color = 'var(--red)'; msg.textContent = e.message; } } },
    body: `<p class="muted" style="margin:0;font-size:14px">Serve un account Instagram <b>professionale</b> (Creator o Business) collegato a una pagina Facebook. Si fa una volta:</p>
      <ol class="ap-steps"><li>Apri <a href="https://developers.facebook.com/apps" target="_blank" rel="noopener">developers.facebook.com</a> e crea un'app (tipo “Business”).</li><li>Apri lo <a href="https://developers.facebook.com/tools/explorer/" target="_blank" rel="noopener">Explorer della Graph API</a>, scegli la tua app e aggiungi i permessi <code>pages_show_list</code>, <code>pages_read_engagement</code>, <code>instagram_basic</code>, <code>instagram_manage_insights</code>.</li><li>Premi <b>Generate Access Token</b>, poi rendilo “a lunga durata” dal <a href="https://developers.facebook.com/tools/debug/accesstoken/" target="_blank" rel="noopener">Debugger dei token</a> (Extend Access Token: dura 60 giorni).</li><li>Incolla qui il token.</li></ol>
      <input class="input" id="mtT" type="password" autocomplete="off" placeholder="Token di accesso Meta (EAA…)"><p id="mtMsg" style="margin:0;font-size:14px"></p>
      <p class="muted" style="margin:0;font-size:13px">Il token è cifrato e segue il tuo account Orbita: non finisce nel codice né nella versione su GitHub. Orbita legge solo follower e risultati dei post; non pubblica nulla al posto tuo.</p>` });
}

/* ---------- AI sheets ---------- */
function socPick(cb, title) { const A = Soc.A(); if (!A.length) return acctEdit(); if (A.length === 1) return cb(A[0]); openSheet({ title: title || 'Per quale pagina?', left: { label: 'Annulla' }, body: `<div class="list">${A.map(a => `<button class="row" data-pk="${a.id}"><span style="font-size:22px">${Soc.net(a).e}</span><span class="grow" style="text-align:left"><div class="t">${esc(a.name)}</div><div class="s">${Soc.net(a).n}${a.handle ? ' · ' + esc(a.handle) : ''}</div></span></button>`).join('')}</div>`, onMount: el => $$('[data-pk]', el).forEach(b => b.onclick = () => { Sheets[Sheets.length - 1].close(); cb(Soc.acct(b.dataset.pk)); }) }); }
ACT.socIdeas = () => socPick(async a => { const L = await Soc.ideas(a); if (!L.length) return; openSheet({ title: '💡 Idee per ' + a.name, wide: true, left: { label: 'Chiudi' }, body: `<div class="soc-ideas">${L.map((x, i) => `<div class="soc-idea"><div class="soc-ifmt">${esc(x.format || '')}</div><b>${esc(x.title)}</b><p>🪝 ${esc(x.hook || '')}</p><small>${esc(x.why || '')}</small><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn sm primary" data-iw="${i}">✨ Scrivilo</button><button class="btn sm" data-is="${i}">Salva l'idea</button></div></div>`).join('')}</div>`,
  onMount: el => { const add = (x, st) => { const p = { id: uid(), acct: a.id, st, title: x.title, hook: x.hook, fmt: x.format, caption: '', tags: [], date: '', time: '', notes: x.why || '', created: Date.now() }; Soc.P().push(p); Soc.save(); return p; };
    $$('[data-is]', el).forEach(b => b.onclick = () => { add(L[+b.dataset.is], 'idea'); b.textContent = '✓ Salvata'; b.disabled = true; App.refresh(); });
    $$('[data-iw]', el).forEach(b => b.onclick = async () => { const x = L[+b.dataset.iw], p = add(x, 'bozza'); const r = await Soc.write(a, p, /reel|video|short|tiktok/i.test(x.format || '') ? 'script' : 'caption'); if (r && r.caption) { p.caption = r.caption; p.tags = (r.hashtags || []).map(t => t.startsWith('#') ? t : '#' + t); p.tip = r.tip || ''; Soc.save(); } Sheets.slice().forEach(s => s.close()); postEdit(p.id); }); } }); }, 'Idee per quale pagina?');
ACT.socPlan = () => socPick(async a => { const L = await Soc.plan(a, 7, Math.max(1, a.per || 3)); if (!L.length) return; const ok = L.map(() => true);
  openSheet({ title: '🗓️ Piano della settimana · ' + a.name, wide: true, left: { label: 'Annulla' }, right: { label: 'Metti in agenda', act: s => { let n = 0; L.forEach((x, i) => { if (!ok[i]) return; Soc.P().push({ id: uid(), acct: a.id, st: 'prog', title: x.title, hook: x.hook, fmt: x.format, caption: x.caption || '', tags: (x.hashtags || []).map(t => t.startsWith('#') ? t : '#' + t), date: x.date, time: /^\d\d:\d\d$/.test(x.time || '') ? x.time : '18:00', notes: '', created: Date.now() }); n++; }); Soc.save(); Alerts.sync && Alerts.sync(); s.close(); App.refresh(); Island.toast({ icon: 'cal', c: 'var(--green)', t: `${n} post in agenda`, s: 'Ti avviso all\'ora di pubblicarli', ms: 2800 }); } },
    body: `<p class="muted" style="margin:0;font-size:14px">Testi pronti, agli orari migliori per questa pagina. Togli la spunta a quelli che non vuoi.</p><div class="list">${L.map((x, i) => `<div class="row" style="align-items:flex-start"><button class="check on" data-pl="${i}" aria-label="Includi"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg></button><span class="grow" style="min-width:0"><div class="t">${esc(x.title)}</div><div class="s">${esc(relDay(x.date, true))} alle ${esc(x.time || '')} · ${esc(x.format || '')}</div><div class="s soc-prev">${esc((x.caption || '').slice(0, 220))}${(x.caption || '').length > 220 ? '…' : ''}</div></span></div>`).join('')}</div>`,
    onMount: el => $$('[data-pl]', el).forEach(b => b.onclick = () => { const i = +b.dataset.pl; ok[i] = !ok[i]; b.classList.toggle('on', ok[i]); }) }); }, 'Piano per quale pagina?');
ACT.socReply = () => socPick(a => { openSheet({ title: '💬 Rispondi a un commento', wide: true, left: { label: 'Chiudi' }, body: `<textarea class="input" id="rpC" rows="3" placeholder="Incolla il commento o il messaggio ricevuto"></textarea><button class="btn primary" id="rpGo" style="align-self:flex-start">✨ Proponi risposte</button><div id="rpR"></div>`,
  onMount: el => { $('#rpGo', el).onclick = async () => { const c = $('#rpC', el).value.trim(); if (!c) return; const r = await Soc.reply(a, c), R = (r && r.r) || []; $('#rpR', el).innerHTML = R.map((x, i) => `<button class="soc-var" data-rc="${i}"><b>${esc(x.tone)}</b><span>${esc(x.text)}</span><small>tocca per copiare</small></button>`).join(''); $$('[data-rc]', el).forEach(b => b.onclick = async () => { try { await navigator.clipboard.writeText(R[+b.dataset.rc].text); } catch (_) {} Island.toast({ icon: 'copy', c: 'var(--green)', t: 'Risposta copiata', ms: 1600 }); }); }; } }); });
ACT.socInsight = () => socPick(async a => { const r = await Soc.insight(a); if (!r) return; openSheet({ title: '📊 Com\'è andata · ' + a.name, wide: true, left: { label: 'Chiudi' }, body: `<p style="margin:0;font-size:15px">${esc(r.summary || '')}</p>${[['✅ Funziona', r.good], ['⚠️ Da migliorare', r.bad], ['🎯 Prossima settimana', r.todo]].map(([h, L]) => L && L.length ? `<div class="field"><span class="lbl">${h}</span><ul class="soc-ul">${L.map(x => `<li>${esc(x)}</li>`).join('')}</ul></div>` : '').join('')}` }); });
ACT.socNew = () => postEdit(null);
ACT.socAcct = el => acctEdit(el && el.dataset ? el.dataset.id : null);
ACT.socMeta = () => metaConnect();
ACT.socSync = () => Soc.sync(true);
ACT.socStats = () => { const A = Soc.A(); if (!A.length) return acctEdit(); openSheet({ title: 'Aggiorna i numeri', left: { label: 'Annulla' }, right: { label: 'Salva', act: s => { A.forEach(a => { const v = $('#sf' + a.id, s.el); if (v && v.value !== '') Soc.stat(a, +v.value); }); Soc.save(); s.close(); App.refresh(); } }, body: `<p class="muted" style="margin:0;font-size:14px">Follower di oggi: bastano una volta a settimana per vedere la crescita.</p><div class="list">${A.map(a => `<div class="row"><span style="font-size:20px">${Soc.net(a).e}</span><span class="grow"><div class="t">${esc(a.name)}</div><div class="s">Ultimo: ${Soc.followers(a) ?? '—'}</div></span><input class="input" id="sf${a.id}" type="number" min="0" style="width:120px" ${a.meta ? 'disabled placeholder="da Meta"' : `placeholder="${Soc.followers(a) ?? ''}"`}></div>`).join('')}</div>` }); };

/* ---------- the page ---------- */
const spark = (vals, c) => { if (vals.length < 2) return ''; const mn = Math.min(...vals), mx = Math.max(...vals), W = 120, H = 34, r = mx - mn || 1; const pts = vals.map((v, i) => `${(i / (vals.length - 1) * W).toFixed(1)},${(H - 3 - (v - mn) / r * (H - 6)).toFixed(1)}`).join(' '); return `<svg class="soc-spark" viewBox="0 0 ${W} ${H}" aria-hidden="true"><polyline points="${pts}" fill="none" stroke="${c}" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`; };
VIEWS.social = {
  actions: () => `<button class="btn sm" data-act="socIdeas">💡<span class="hide-narrow">Idee</span></button><button class="btn primary sm" data-act="socNew">${ico('plus', 'sm')}Post</button>`,
  render() {
    const A = Soc.A(), t = todayK(), sel = UI.socA && Soc.acct(UI.socA) ? UI.socA : 'all', Ps = Soc.P().filter(p => sel === 'all' || p.acct === sel);
    if (!A.length) return `<h1 class="large-title">Social</h1><p class="subtitle">Le tue pagine in un posto solo: piano editoriale, testi e idee con l'IA, orari migliori e crescita.</p>
      <div class="card soc-empty"><div style="font-size:44px">📣</div><b>Aggiungi la tua prima pagina</b><p class="muted">Instagram, TikTok, Facebook, LinkedIn, YouTube, X o Threads.</p><div style="display:flex;gap:8px;flex-wrap:wrap;justify-content:center"><button class="btn primary" data-act="socAcct">${ico('plus', 'sm')}Aggiungi una pagina</button><button class="btn" data-act="socMeta">📸 Collega Instagram / Facebook</button></div></div>`;
    const week = [...Array(7)].map((_, i) => addDK(t, i));
    const accCard = a => { const N = Soc.net(a), f = Soc.followers(a), g = Soc.growth(a), w = Soc.week(a), vals = (a.stats || []).slice(-30).map(x => x.f); return `<button class="soc-acc ${sel === a.id ? 'on' : ''}" data-socsel="${a.id}" style="--nc:${N.c}"><div class="soc-acc-h"><span class="soc-ne">${N.e}</span><span class="grow" style="min-width:0"><b>${esc(a.name)}</b><small>${N.n}${a.handle ? ' · ' + esc(a.handle) : ''}${a.meta ? ' · 🔗' : ''}</small></span><span class="soc-ed" data-act="socAcct" data-id="${a.id}" role="button" aria-label="Modifica">${ico('more', 'sm')}</span></div>
      <div class="soc-acc-n"><span><b class="tnum">${f != null ? f.toLocaleString('it-IT') : '—'}</b><small>follower${g ? ` · <span style="color:${g > 0 ? 'var(--green)' : 'var(--red)'}">${g > 0 ? '+' : ''}${g.toLocaleString('it-IT')}</span>/30g` : ''}</small></span>${spark(vals, N.c)}</div>
      <div class="soc-goal"><i style="width:${Math.min(100, Math.round(w / (a.per || 3) * 100))}%"></i></div><small class="muted">${w}/${a.per || 3} post questa settimana</small></button>`; };
    const dayCol = k => { const L = Ps.filter(p => (p.st === 'prog' || p.st === 'pub') && p.date === k).sort((x, y) => (x.time || '').localeCompare(y.time || '')); return `<div class="soc-day ${k === t ? 'today' : ''}"><div class="soc-dh"><b>${k === t ? 'Oggi' : cap(DOW_IT[parseD(k).getDay()])}</b><small>${parseD(k).getDate()}</small></div>${L.map(p => { const a = Soc.acct(p.acct), N = Soc.net(a); return `<button class="soc-pc ${p.st}" data-post="${p.id}" style="--nc:${N.c}"><small>${N.e} ${p.time || ''}</small><span>${esc(p.title || (p.caption || '').slice(0, 40) || 'Post')}</span></button>`; }).join('')}<button class="soc-add" data-postnew="${k}" aria-label="Aggiungi un post">+</button></div>`; };
    const ideas = Ps.filter(p => p.st === 'idea' || p.st === 'bozza').sort((x, y) => (y.created || 0) - (x.created || 0)), toRate = Ps.filter(p => p.st === 'pub' && !p.perf && p.date && dayDiff(p.date, t) >= 2).slice(0, 5);
    const aSel = sel !== 'all' ? Soc.acct(sel) : A[0], heat = aSel ? Soc.heat(aSel) : null, top = aSel ? Soc.slots(aSel, 3) : [];
    const pub = Ps.filter(p => p.st === 'pub' && p.perf).concat(sel === 'all' ? A.flatMap(a => (a.media || []).map(m => ({ ...m, acct: a.id, media: 1 }))) : ((Soc.acct(sel) || {}).media || []).map(m => ({ ...m, acct: sel, media: 1 }))).sort((x, y) => Soc.eng(y) - Soc.eng(x)).slice(0, 5);
    return `<h1 class="large-title">Social</h1><p class="subtitle">Piano editoriale, testi e idee con l'IA, orari migliori e crescita delle tue pagine.</p>
      <div class="soc-accs"><button class="soc-all ${sel === 'all' ? 'on' : ''}" data-socsel="all">Tutte</button>${A.map(accCard).join('')}<button class="soc-acc soc-newacc" data-act="socAcct">${ico('plus')}<b>Pagina</b></button></div>
      <div class="soc-tools">${[['socIdeas', '💡', 'Idee', 'su misura per la pagina'], ['socNew', '✍️', 'Scrivi un post', 'testo, hashtag, varianti'], ['socPlan', '🗓️', 'Piano della settimana', 'pronto e in agenda'], ['socReply', '💬', 'Rispondi', 'a commenti e messaggi'], ['socInsight', '📊', 'Analizza', 'cosa funziona']].map(([a, e, t2, s]) => `<button class="soc-tool" data-act="${a}"><span>${e}</span><b>${t2}</b><small>${s}</small></button>`).join('')}</div>
      <div class="section-h">Prossimi 7 giorni</div><div class="soc-week">${week.map(dayCol).join('')}</div>
      ${toRate.length ? `<div class="card soc-rate"><b>📈 Com'è andata?</b><p class="muted" style="margin:2px 0 8px;font-size:14px">Segna i risultati: Orbita impara i tuoi orari migliori.</p><div class="chips">${toRate.map(p => `<button class="chip" data-post="${p.id}">${Soc.net(Soc.acct(p.acct)).e} ${esc(p.title || 'Post')} · ${relDay(p.date)}</button>`).join('')}</div></div>` : ''}
      <div class="grid dash" style="margin-top:16px">
        <section class="card span-6"><div class="card-h"><h3>💡 Idee e bozze</h3><span class="more muted" style="color:var(--label-2)">${ideas.length}</span></div>${ideas.length ? `<div class="list flat" style="box-shadow:none;margin:0 -8px">${ideas.slice(0, 8).map(p => { const a = Soc.acct(p.acct); return `<button class="row" data-post="${p.id}"><span style="font-size:20px">${PST_ST[p.st][1]}</span><span class="grow" style="min-width:0;text-align:left"><div class="t">${esc(p.title || (p.caption || '').slice(0, 50) || 'Senza titolo')}</div><div class="s">${Soc.net(a).e} ${esc(a ? a.name : '')}${p.fmt ? ' · ' + esc(p.fmt) : ''}</div></span>${ico('right', 'sm')}</button>`; }).join('')}</div>` : `<div class="empty" style="padding:18px">${ico('spark')}<b>Nessuna idea salvata</b><button class="btn sm primary" data-act="socIdeas">💡 Chiedi idee all'IA</button></div>`}</section>
        <section class="card span-6"><div class="card-h"><h3>⏱️ Quando pubblicare</h3>${aSel ? `<span class="more muted" style="color:var(--label-2)">${Soc.net(aSel).e} ${esc(aSel.name)}</span>` : ''}</div>${aSel ? `<p class="muted" style="margin:-4px 0 8px;font-size:13.5px">${heat.own ? `Calcolato su ${heat.n} tuoi post.` : `Indicazioni generali per ${Soc.net(aSel).n}: con 6 post pubblicati e i loro risultati diventano i tuoi orari.`}</p><div class="soc-best">${top.map((s, i) => `<span class="soc-bs ${i ? '' : 'top'}"><b>${cap(DOW_IT[s.d])}</b> ${pad(s.h)}:00</span>`).join('')}</div>${socHeat(heat.H, Soc.net(aSel).c)}` : ''}</section>
        <section class="card span-12"><div class="card-h"><h3>🏆 Post migliori</h3>${A.some(a => a.meta) ? `<button class="more" data-act="socSync">${ico('refresh', 'sm')}Aggiorna</button>` : `<button class="more" data-act="socStats">Aggiorna i numeri</button>`}</div>${pub.length ? `<div class="list flat" style="box-shadow:none;margin:0 -8px">${pub.map(p => { const a = Soc.acct(p.acct), m = p.perf || {}; return `<${p.media ? `a href="${esc(p.link || '#')}" target="_blank" rel="noopener"` : `button data-post="${p.id}"`} class="row"><span style="font-size:20px">${Soc.net(a).e}</span><span class="grow" style="min-width:0;text-align:left"><div class="t">${esc((p.title || p.cap || p.caption || 'Post').slice(0, 80))}</div><div class="s">${relDay(p.date || p.k)} · ❤️ ${m.likes || 0} · 💬 ${m.comments || 0}${m.shares ? ' · ↗︎ ' + m.shares : ''}${m.views ? ' · 👁 ' + m.views : ''}</div></span></${p.media ? 'a' : 'button'}>`; }).join('')}</div>` : `<p class="muted" style="margin:0">Quando pubblichi, segna i risultati (o collega Instagram/Facebook) e qui vedi cosa funziona di più.</p>`}
          <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px">${A.some(a => a.meta) ? '' : `<button class="btn sm" data-act="socMeta">📸 Collega Instagram / Facebook</button>`}<button class="btn sm plain" data-act="socStats">Aggiorna i follower</button><button class="btn sm plain" data-act="socSet">Impostazioni</button></div>${S.social.err && A.some(a => a.meta) ? `<p style="color:var(--orange);font-size:13px;margin:8px 0 0">${esc(S.social.err)}</p>` : ''}</section></div>`;
  },
  mount(root) {
    $$('[data-socsel]', root).forEach(b => b.onclick = e => { if (e.target.closest('[data-act]')) return; UI.socA = b.dataset.socsel; App.refresh(); });
    $$('[data-post]', root).forEach(b => b.onclick = () => postEdit(b.dataset.post));
    $$('[data-postnew]', root).forEach(b => b.onclick = () => { const A = Soc.A(), a = (UI.socA && Soc.acct(UI.socA)) || A[0]; const k = b.dataset.postnew, H = Soc.heat(a).H[parseD(k).getDay()]; let h = 18, v = -1; H.forEach((x, i) => { if (i >= 8 && x > v && (k !== todayK() || i > new Date().getHours())) { v = x; h = i; } }); postEdit(null, { acct: a.id, st: 'prog', date: k, time: pad(h) + ':00' }); });
    Soc.sync().catch(() => {});
  },
};
function socHeat(H, c) { const B = [[7, 10], [10, 13], [13, 16], [16, 19], [19, 22], [22, 24]], mx = Math.max(...H.flat(), .01), order = [1, 2, 3, 4, 5, 6, 0];
  return `<div class="soc-heat"><span></span>${B.map(b => `<small>${b[0]}</small>`).join('')}${order.map(d => `<small>${cap(DOW_IT[d])}</small>${B.map(([a, b]) => { let v = 0; for (let h = a; h < b; h++) v = Math.max(v, H[d][h]); return `<i style="background:color-mix(in srgb,${c} ${Math.round(v / mx * 85)}%,var(--fill))" title="${cap(DOW_IT[d])} ${a}-${b}"></i>`; }).join('')}`).join('')}</div>`; }
ACT.socSet = () => openSheet({ title: 'Social', left: { label: 'Fine', act: s => { s.close(); App.refresh(); } }, body: `<div class="list flat"><div class="row"><span class="grow"><div class="t">Avvisami all'ora di pubblicare</div><div class="s">Notifica con il testo pronto da copiare</div></span>${toggleBtn('ssN', S.social.notif !== false)}</div><div class="row"><span class="grow"><div class="t">Scheda Social su Oggi</div></span>${toggleBtn('ssT', S.social.today !== false)}</div>${AIK.has('meta') ? `<div class="row"><span class="grow"><div class="t">Instagram / Facebook collegati</div><div class="s">Token Meta cifrato · dura 60 giorni</div></span><button class="btn sm" id="ssR">Rinnova</button><button class="btn sm danger" id="ssX">Scollega</button></div>` : ''}</div>`,
  onMount: el => { wireToggle($('#ssN', el), v => { S.social.notif = v; Soc.save(); Alerts.sync && Alerts.sync(); }); wireToggle($('#ssT', el), v => { S.social.today = v; Soc.save(); }); const r = $('#ssR', el); if (r) r.onclick = () => metaConnect(); const x = $('#ssX', el); if (x) x.onclick = async () => { await AIK.set('meta', ''); Soc.A().forEach(a => delete a.meta); Soc.save(); Sheets.slice().forEach(s => s.close()); App.refresh(); }; } });

/* ---------- Today ---------- */
TODAY_CARDS.social = 'Social'; if (!TODAY_DEFAULT.includes('social')) TODAY_DEFAULT.push('social');
TODAY_EXTRA.social = () => { const A = Soc.A(); if (!A.length || S.social.today === false) return ''; const t = todayK(), L = Soc.P().filter(p => p.st === 'prog' && (p.date === t || p.date === addDK(t, 1))).sort((x, y) => (x.date + x.time).localeCompare(y.date + y.time)), behind = A.filter(a => Soc.week(a) < (a.per || 3) && Soc.P().filter(p => p.acct === a.id && p.st === 'prog' && p.date > t).length === 0);
  return `<section class="card span-6"><div class="card-h"><h3>📣 Social</h3><button class="more" data-go="social">Apri${ico('right', 'sm')}</button></div>${L.length ? `<div class="list flat" style="box-shadow:none;margin:0 -8px">${L.slice(0, 4).map(p => { const a = Soc.acct(p.acct); return `<button class="row" data-open="social:${p.id}"><span style="font-size:20px">${Soc.net(a).e}</span><span class="grow" style="min-width:0;text-align:left"><div class="t">${esc(p.title || 'Post')}</div><div class="s">${p.date === t ? 'Oggi' : 'Domani'} alle ${p.time || '—'} · ${esc(a ? a.name : '')}</div></span></button>`; }).join('')}</div>` : '<p class="muted" style="margin:0 0 6px">Niente da pubblicare oggi e domani.</p>'}
    ${behind.length ? `<div class="soc-behind">${behind.slice(0, 2).map(a => `<span>${Soc.net(a).e} ${esc(a.name)}: ${Soc.week(a)}/${a.per || 3} questa settimana</span>`).join('')}<button class="btn sm" data-act="socPlan">🗓️ Preparami la settimana</button></div>` : ''}</section>`; };
if (typeof TodaySmart !== 'undefined' && TodaySmart.score) { const oS = TodaySmart.score.bind(TodaySmart); TodaySmart.score = function (k, ...a) { if (k === 'social') return Soc.P().some(p => p.st === 'prog' && p.date === todayK()) ? 70 : 0; return oS(k, ...a); }; }
CMD_ACT.push(['Social: nuovo post', 'share', () => postEdit(null)], ['Social: idee con l\'IA', 'spark', () => ACT.socIdeas()], ['Social: piano della settimana', 'cal', () => ACT.socPlan()], ['Social: rispondi a un commento', 'chat', () => ACT.socReply()]);
CMD_SRC.push(q => q.length < 3 ? [] : Soc.P().filter(p => ((p.title || '') + ' ' + (p.caption || '')).toLowerCase().includes(q)).slice(0, 5).map(p => ({ sec: 'Social', t: p.title || (p.caption || '').slice(0, 50), s: `${PST_ST[p.st][0]}${p.date ? ' · ' + relDay(p.date) : ''}`, i: 'share', fn: () => postEdit(p.id) })));
/* the assistant can plan posts too */
Promise.resolve().then(() => { if (typeof Assistant === 'undefined') return; const old = Assistant.tools.bind(Assistant); Assistant.tools = function () { return old().concat([{ name: 'social_posts', description: 'Elenca le pagine social e i post programmati, le idee e i risultati recenti.', inputSchema: { type: 'object', properties: {} }, execute() { return { pagine: Soc.A().map(a => ({ nome: a.name, social: Soc.net(a).n, follower: Soc.followers(a), crescita_30g: Soc.growth(a), post_settimana: Soc.week(a), obiettivo_settimana: a.per })), post: Soc.P().filter(p => p.st !== 'pub' || dayDiff(p.date || todayK(), todayK()) < 14).map(p => ({ titolo: p.title, stato: PST_ST[p.st][0], data: p.date, ora: p.time, pagina: (Soc.acct(p.acct) || {}).name })) }; } }]); }; });

