    const fem = pool.find(v => /alice|federica|elsa|isabella|paola|emma|chiara|female|donna|f\b/i.test(v.name)), mal = pool.find(v => v !== fem && /luca|diego|giorgio|cosimo|marco|male|uomo|m\b/i.test(v.name));
