      try { const before = new Set(S.docs.map(d => d.id)), old = UI.docFilter; UI.docFilter = 'all'; await Docs.upload([file]); UI.docFilter = old; const d = S.docs.find(z => !before.has(z.id)); if (d) { d.subject = c.name; save('docs'); } } catch (_) {}
